// 病句 코스 7 — tools/make_bingju.py 가 tools/bingju/c07.json 에서 만든다. 직접 고치지 않는다.
(window.BJ=window.BJ||{})[7]=[[{"o":["经过历代书法家的临摹与研习，使颜真卿雄浑厚重的楷书风格深刻影响了此后一千多年的书坛。","云南的普洱茶以其独特的后发酵工艺著称，存放时间越长，口感往往越醇厚。","舟山渔场是我国最大的近海渔场，盛产大黄鱼、小黄鱼、带鱼和墨鱼，素有“东海鱼仓”之称。","面对日益激烈的市场竞争，这家老字号既坚守传统技艺，又积极尝试线上销售，赢得了年轻消费者的青睐。"],"a":0,"type":"주어 결여","why":"“经过…，使…” 때문에 문장에 주어가 없다. ‘影响’한 것이 무엇인지 말할 자리가 비었다.","fix":"经过历代书法家的临摹与研习，颜真卿雄浑厚重的楷书风格深刻影响了此后一千多年的书坛。","words":[["临摹","línmó","(글씨·그림을) 본떠 쓰다"],["雄浑","xiónghún","웅장하고 힘차다"],["醇厚","chúnhòu","(맛이) 진하고 깊다"],["老字号","lǎozìhao","오래된 이름난 가게"],["青睐","qīnglài","호감, 인기"],["渔场","yúchǎng","어장"],["盛产","shèngchǎn","많이 나다"]],"tr":["역대 서예가들이 본떠 쓰고 연구한 덕분에 안진경의 웅장하고 묵직한 해서 풍격은 그 뒤 천여 년 동안 서예계에 깊은 영향을 주었다.","윈난의 보이차는 독특한 후발효 공법으로 유명하며, 오래 묵힐수록 맛이 대개 더 진하고 깊어진다.","저우산 어장은 중국에서 가장 큰 근해 어장으로, 참조기·부세·갈치·갑오징어가 많이 나서 예로부터 '동해의 물고기 창고'라 불린다.","갈수록 치열해지는 시장 경쟁 속에서 이 노포는 전통 기술을 지키면서도 온라인 판매를 적극 시도해 젊은 소비자들의 호감을 얻었다."],"ow":[[["临摹","línmó","본떠 쓰다"],["研习","yánxí","연구하고 익히다"],["颜真卿","Yán Zhēnqīng","안진경(당대 서예가)"],["雄浑","xiónghún","웅장하고 힘차다"],["楷书","kǎishū","해서"],["书坛","shūtán","서예계"]],[["普洱茶","pǔ'ěrchá","보이차"],["发酵","fājiào","발효하다"],["工艺","gōngyì","공법, 기술"],["著称","zhùchēng","유명하다"],["醇厚","chúnhòu","진하고 깊다"]],[["舟山","Zhōushān","저우산(저장성의 군도)"],["渔场","yúchǎng","어장"],["盛产","shèngchǎn","많이 나다"],["带鱼","dàiyú","갈치"],["墨鱼","mòyú","갑오징어"],["素有","sùyǒu","예로부터 ~을 지니다"]],[["日益","rìyì","날로"],["老字号","lǎozìhao","오래된 이름난 가게"],["坚守","jiānshǒu","굳게 지키다"],["技艺","jìyì","기예, 기술"],["青睐","qīnglài","호감, 인기"]]]},{"o":["厦门鼓浪屿上钢琴的人均拥有量曾居全国首位，这座小岛因此被誉为“钢琴之岛”。","随着数字修复技术的日益成熟，使许多因年代久远而严重褪色的老电影胶片重新呈现出当年的光彩。","浙江象山每年九月举办中国开渔节，渔民们在锣鼓声中扬帆出海，祈求平安丰收。","这项调查显示，长期睡眠不足不仅会削弱人的记忆力，还可能导致情绪波动加剧。"],"a":1,"type":"주어 결여","why":"“随着…，使…” 때문에 주어가 없다. ‘使’를 빼야 ‘老电影胶片’이 주어가 된다.","fix":"随着数字修复技术的日益成熟，许多因年代久远而严重褪色的老电影胶片重新呈现出当年的光彩。","words":[["褪色","tuìsè","색이 바래다"],["胶片","jiāopiàn","필름"],["削弱","xuēruò","약하게 하다"],["鼓浪屿","Gǔ làng yǔ","구랑위(샤먼의 섬)"],["开渔节","kāiyújié","어로 시작 축제"],["扬帆","yángfān","돛을 올리다"],["祈求","qíqiú","간절히 바라다"]],"tr":["샤먼 구랑위의 1인당 피아노 보유량은 한때 전국 1위였고, 그래서 이 작은 섬은 '피아노의 섬'이라 불린다.","디지털 복원 기술이 날로 성숙해지면서, 오래되어 심하게 색이 바랜 옛 영화 필름들이 당시의 빛을 다시 되찾았다.","저장성 샹산에서는 해마다 9월에 중국 개어절을 열고, 어민들은 징과 북소리 속에 돛을 올려 바다로 나가며 무사와 풍어를 빈다.","이 조사에 따르면 오랜 수면 부족은 기억력을 떨어뜨릴 뿐 아니라 감정 기복을 더 심하게 만들 수도 있다."],"ow":[[["厦门","Xiàmén","샤먼"],["鼓浪屿","Gǔlàng Yǔ","구랑위(섬 이름)"],["人均","rénjūn","1인당"],["被誉为","bèi yùwéi","~로 칭송되다"]],[["修复","xiūfù","복원하다"],["日益","rìyì","날로"],["褪色","tuìsè","색이 바래다"],["胶片","jiāopiàn","필름"],["呈现","chéngxiàn","나타내다"]],[["象山","Xiàngshān","샹산(저장성의 현)"],["开渔节","kāiyújié","어로 시작 축제"],["锣鼓","luógǔ","징과 북"],["扬帆","yángfān","돛을 올리다"],["祈求","qíqiú","간절히 빌다"]],[["削弱","xuēruò","약하게 하다"],["波动","bōdòng","기복, 변동"],["加剧","jiājù","심해지다"]]]},{"o":["舟山渔民画以大胆夸张的造型和浓烈鲜艳的色彩，生动地再现了海岛渔民的劳作场景与生活习俗。","都江堰水利工程历经两千多年仍在发挥作用，堪称古代水利史上的奇迹。","在老一辈艺术家的悉心指导和严格要求下，让这些年轻的京剧演员在短短三年内就掌握了大量传统剧目。","人体内的维生素D大部分是皮肤在阳光照射下合成的，因此适当晒太阳有益于骨骼健康。"],"a":2,"type":"주어 결여","why":"“在…下，让…” 때문에 주어가 없다. ‘让’을 빼야 ‘年轻的京剧演员’이 주어가 된다.","fix":"在老一辈艺术家的悉心指导和严格要求下，这些年轻的京剧演员在短短三年内就掌握了大量传统剧目。","words":[["都江堰","Dū jiāng yàn","두장옌(쓰촨의 고대 수리 시설)"],["堪称","kānchēng","~라고 할 만하다"],["悉心","xīxīn","온 마음을 다해"],["剧目","jùmù","공연 레퍼토리"],["夸张","kuāzhāng","과장하다"],["浓烈","nóngliè","짙고 강렬하다"],["再现","zàixiàn","재현하다"]],"tr":["저우산 어민화는 과감하게 과장한 형태와 짙고 화려한 색채로 섬 어민들의 일하는 모습과 생활 풍습을 생생하게 그려 냈다.","두장옌 수리 시설은 2천여 년이 지나도록 여전히 제 역할을 하고 있어 고대 수리사의 기적이라 할 만하다.","선배 예술가들의 세심한 지도와 엄격한 요구 아래, 이 젊은 경극 배우들은 불과 3년 만에 수많은 전통 레퍼토리를 익혔다.","몸속 비타민 D는 대부분 햇볕을 받은 피부에서 합성되므로, 적당히 햇볕을 쬐는 것은 뼈 건강에 좋다."],"ow":[[["渔民画","yúmínhuà","어민화(어민이 그린 민간 그림)"],["夸张","kuāzhāng","과장하다"],["浓烈","nóngliè","짙고 강렬하다"],["再现","zàixiàn","재현하다"],["习俗","xísú","풍습"]],[["都江堰","Dūjiāngyàn","두장옌(쓰촨의 고대 수리 시설)"],["历经","lìjīng","두루 겪다"],["堪称","kānchēng","~라 할 만하다"],["奇迹","qíjì","기적"]],[["悉心","xīxīn","온 마음을 다해"],["京剧","jīngjù","경극"],["剧目","jùmù","공연 레퍼토리"]],[["维生素","wéishēngsù","비타민"],["照射","zhàoshè","비추다"],["合成","héchéng","합성하다"],["骨骼","gǔgé","뼈, 골격"]]]},{"o":["沈从文的《边城》以湘西小镇茶峒为背景，用清新质朴的笔调描绘了一段纯美而忧伤的爱情故事。","研究人员发现，某些植物在遭到昆虫啃食时会释放特定的化学物质，以吸引害虫的天敌前来捕食。","这座古城的街巷格局基本保留了明清时期的原貌，每年吸引着数以百万计的游客前来参观。","由于这位导演对细节近乎苛刻的追求和对历史资料的反复考证，令这部历史剧在服装和布景上几乎无可挑剔。"],"a":3,"type":"주어 결여","why":"“由于…，令…” 때문에 주어가 없다. ‘令’을 빼야 ‘这部历史剧’가 주어가 된다.","fix":"由于这位导演对细节近乎苛刻的追求和对历史资料的反复考证，这部历史剧在服装和布景上几乎无可挑剔。","words":[["茶峒","Chá dòng","차둥(후난 서부의 작은 마을)"],["质朴","zhìpǔ","소박하다"],["笔调","bǐdiào","글의 필치"],["啃食","kěnshí","갉아먹다"],["苛刻","kēkè","가혹하다, 지나치게 까다롭다"],["考证","kǎozhèng","고증하다"],["无可挑剔","wú kě tiāo tī","흠잡을 데가 없다"]],"tr":["선충원의 『변성』은 후난 서부의 작은 마을 차둥을 배경으로, 맑고 소박한 필치로 순수하면서도 슬픈 사랑 이야기를 그렸다.","연구진은 어떤 식물들이 곤충에게 갉아먹힐 때 특정 화학 물질을 내뿜어 해충의 천적을 불러들인다는 것을 발견했다.","이 옛 도시의 거리와 골목 배치는 명·청 시대의 원래 모습을 거의 그대로 간직하고 있어 해마다 수백만 명의 관광객을 끌어들인다.","감독이 세부까지 거의 가혹할 만큼 공을 들이고 역사 자료를 거듭 고증한 덕분에, 이 사극은 의상과 무대 장치에서 흠잡을 데가 거의 없다."],"ow":[[["沈从文","Shěn Cóngwén","선충원(작가)"],["边城","Biānchéng","변성(소설 제목)"],["茶峒","Chádòng","차둥(마을 이름)"],["质朴","zhìpǔ","소박하다"],["笔调","bǐdiào","필치"]],[["啃食","kěnshí","갉아먹다"],["释放","shìfàng","방출하다"],["天敌","tiāndí","천적"],["捕食","bǔshí","잡아먹다"]],[["格局","géjú","구조, 배치"],["原貌","yuánmào","원래 모습"],["数以百万计","shù yǐ bǎiwàn jì","수백만에 이르다"]],[["苛刻","kēkè","지나치게 까다롭다"],["考证","kǎozhèng","고증하다"],["布景","bùjǐng","무대 장치, 세트"],["无可挑剔","wú kě tiāotī","흠잡을 데가 없다"]]]},{"o":["学校希望通过开设书法、篆刻和古琴等选修课程，使学生对中华传统艺术的了解和兴趣。","妈祖是东南沿海一带渔民和船工信奉的海上保护神，相关祭祀习俗已被列入非物质文化遗产名录。","这家企业在研发投入上毫不吝啬，每年拿出营业收入的百分之十五用于新技术的开发。","适度的压力能够激发人的潜能，但如果压力长期超出承受范围，反而会损害身心健康。"],"a":0,"type":"술어 결여","why":"“使学生对…的了解和兴趣” 뒤에 동사가 없다. ‘了解’에는 ‘加深’, ‘兴趣’에는 ‘激发’ 같은 동사가 있어야 한다.","fix":"学校希望通过开设书法、篆刻和古琴等选修课程，加深学生对中华传统艺术的了解，激发他们的兴趣。","words":[["篆刻","zhuànkè","전각(도장 새기기)"],["古琴","gǔqín","고금(칠현금)"],["吝啬","lìnsè","인색하다"],["潜能","qiánnéng","잠재력"],["承受","chéngshòu","견디다, 감당하다"],["妈祖","Mā zǔ","마조(바다의 여신)"],["信奉","xìnfèng","믿고 받들다"],["祭祀","jìsì","제사"]],"tr":["학교는 서예·전각·고금 같은 선택 과목을 열어 학생들이 중국 전통 예술을 더 잘 알고 흥미를 갖게 하려 한다.","마조는 동남 연해 지역 어민과 뱃사람들이 믿는 바다의 수호신이며, 이와 관련된 제사 풍습은 무형 문화유산 목록에 올라 있다.","이 기업은 연구 개발 투자에 조금도 인색하지 않아, 해마다 매출의 15%를 신기술 개발에 쓴다.","적당한 스트레스는 사람의 잠재력을 끌어내지만, 스트레스가 오래 감당할 수 있는 범위를 넘으면 오히려 몸과 마음의 건강을 해친다."],"ow":[[["篆刻","zhuànkè","전각(도장 새기기)"],["古琴","gǔqín","고금(칠현금)"],["选修","xuǎnxiū","선택 이수하다"]],[["妈祖","Māzǔ","마조(바다의 여신)"],["沿海","yánhǎi","연해"],["信奉","xìnfèng","믿고 받들다"],["祭祀","jìsì","제사"],["名录","mínglù","명부, 목록"]],[["研发","yánfā","연구 개발"],["毫不","háobù","조금도 ~않다"],["吝啬","lìnsè","인색하다"]],[["适度","shìdù","적당하다"],["激发","jīfā","불러일으키다"],["潜能","qiánnéng","잠재력"],["承受","chéngshòu","감당하다"],["损害","sǔnhài","해치다"]]]},{"o":["中国古代工匠发明的水密隔舱技术，使船只即使局部破损进水，也不至于迅速沉没。","关于如何吸引年轻观众重新走进剧场这一问题，这家百年剧院近年来所做的一系列大胆而富有成效的尝试。","青藏高原平均海拔四千米以上，是长江、黄河等众多大江大河的发源地，被称为“亚洲水塔”。","研究表明，儿童在三岁以前接触的语言环境，对其日后的语言能力有着不可忽视的影响。"],"a":1,"type":"술어 결여","why":"“这家百年剧院近年来所做的一系列…尝试”는 명사 덩어리일 뿐이라 문장에 서술어가 없다.","fix":"关于如何吸引年轻观众重新走进剧场这一问题，这家百年剧院近年来做了一系列大胆而富有成效的尝试。","words":[["成效","chéngxiào","효과, 성과"],["海拔","hǎibá","해발"],["发源地","fāyuándì","발원지"],["水密隔舱","shuǐ mì gé cāng","방수 격벽 칸"],["不至于","búzhìyú","~에 이르지는 않다"]],"tr":["중국 고대 장인들이 발명한 방수 격벽 기술 덕분에, 배는 일부가 부서져 물이 들어와도 금방 가라앉지는 않는다.","젊은 관객을 어떻게 다시 극장으로 불러들일 것인가 하는 문제에 대해, 이 백 년 된 극장은 최근 몇 년간 과감하고 성과 있는 시도를 여럿 해 왔다.","칭짱고원은 평균 해발이 4천 미터를 넘고 창장·황허 등 수많은 큰 강의 발원지여서 '아시아의 급수탑'이라 불린다.","연구에 따르면 아이가 세 살 이전에 접한 언어 환경은 나중의 언어 능력에 무시할 수 없는 영향을 준다."],"ow":[[["工匠","gōngjiàng","장인"],["水密隔舱","shuǐmì gécāng","방수 격벽 칸"],["局部","júbù","일부분"],["不至于","búzhìyú","~에 이르지는 않다"],["沉没","chénmò","가라앉다"]],[["剧场","jùchǎng","극장"],["剧院","jùyuàn","극장"],["成效","chéngxiào","효과, 성과"],["尝试","chángshì","시도"]],[["青藏高原","Qīngzàng Gāoyuán","칭짱고원(티베트 고원)"],["海拔","hǎibá","해발"],["发源地","fāyuándì","발원지"],["水塔","shuǐtǎ","급수탑"]],[["日后","rìhòu","나중, 장래"],["不可忽视","bùkě hūshì","무시할 수 없다"]]]},{"o":["唐代诗人王维的作品融诗情与画意于一体，苏轼曾称赞他“诗中有画，画中有诗”。","为了让海洋鱼类有充足的繁殖时间，我国自上世纪九十年代起在近海实行伏季休渔制度。","针对近年来部分景区门票价格过高、服务质量参差不齐的现象，有关部门出台的一系列整顿措施。","这位科学家毕生致力于杂交水稻的研究，为解决数亿人的温饱问题作出了卓越贡献。"],"a":2,"type":"술어 결여","why":"“有关部门出台的一系列整顿措施”는 명사 덩어리라 ‘针对…’ 뒤에 서술어가 없다. ‘的’를 ‘了’로 바꿔야 한다.","fix":"针对近年来部分景区门票价格过高、服务质量参差不齐的现象，有关部门出台了一系列整顿措施。","words":[["参差不齐","cēn cī bù qí","들쭉날쭉하다"],["整顿","zhěngdùn","정비하다, 바로잡다"],["毕生","bìshēng","평생"],["杂交","zájiāo","교배(잡종)"],["卓越","zhuóyuè","탁월하다"],["伏季休渔","fú jì xiū yú","여름철 금어기"],["繁殖","fánzhí","번식하다"]],"tr":["당나라 시인 왕유의 작품은 시의 정취와 그림의 뜻을 하나로 녹여 내어, 소식은 그를 두고 '시 속에 그림이 있고 그림 속에 시가 있다'고 칭찬했다.","바닷물고기들이 충분히 번식할 시간을 주기 위해, 중국은 1990년대부터 근해에서 여름철 금어기 제도를 시행해 왔다.","최근 일부 관광지의 입장료가 지나치게 비싸고 서비스 질이 들쭉날쭉한 현상을 겨냥해, 관련 부처는 일련의 정비 조치를 내놓았다.","이 과학자는 평생 잡종 벼 연구에 몸 바쳐, 수억 명이 배불리 먹고 따뜻하게 지내는 문제를 해결하는 데 탁월한 공헌을 했다."],"ow":[[["王维","Wáng Wéi","왕유(당대 시인)"],["融","róng","녹여 합치다"],["苏轼","Sū Shì","소식(소동파)"],["称赞","chēngzàn","칭찬하다"]],[["繁殖","fánzhí","번식하다"],["近海","jìnhǎi","근해"],["伏季休渔","fújì xiūyú","여름철 금어기"],["实行","shíxíng","시행하다"]],[["针对","zhēnduì","겨냥하다"],["景区","jǐngqū","관광지"],["参差不齐","cēncī bù qí","들쭉날쭉하다"],["出台","chūtái","(정책을) 내놓다"],["整顿","zhěngdùn","정비하다"]],[["毕生","bìshēng","평생"],["致力于","zhìlìyú","~에 힘쓰다"],["杂交水稻","zájiāo shuǐdào","잡종 벼"],["温饱","wēnbǎo","의식주 기본 생활"],["卓越","zhuóyuè","탁월하다"]]]},{"o":["老舍的话剧《茶馆》通过一个茶馆半个世纪的兴衰，折射出旧中国社会的巨大变迁。","海参在水温升高时会进入夏眠状态，潜伏在礁石底下，几个月不吃不动。","洋山深水港四期是全球规模最大的自动化集装箱码头之一，桥吊和运输车辆均由电脑系统远程调度。","这项远程教学计划大大增加了偏远山区的孩子通过网络接触优质艺术教育的。"],"a":3,"type":"목적어 결여","why":"“增加了…的” 뒤에 꾸밈을 받는 명사가 없다. ‘机会’가 있어야 ‘增加’의 목적어가 된다.","fix":"这项远程教学计划大大增加了偏远山区的孩子通过网络接触优质艺术教育的机会。","words":[["兴衰","xīngshuāi","흥망성쇠"],["折射","zhéshè","(사회상을) 비추어 보이다"],["变迁","biànqiān","변천"],["偏远","piānyuǎn","외지고 멀다"],["海参","hǎishēn","해삼"],["夏眠","xiàmián","여름잠"],["潜伏","qiánfú","숨어 있다"],["集装箱","jízhuāngxiāng","컨테이너"]],"tr":["라오서의 연극 『찻집』은 한 찻집의 반세기에 걸친 흥망을 통해 옛 중국 사회의 거대한 변화를 비추어 보인다.","해삼은 수온이 오르면 여름잠에 들어가 바위 밑에 숨은 채 몇 달 동안 먹지도 움직이지도 않는다.","양산 심수항 4기는 세계 최대 규모의 자동화 컨테이너 부두 가운데 하나로, 안벽 크레인과 운송 차량이 모두 컴퓨터 시스템으로 원격 운영된다.","이 원격 교육 계획은 외딴 산골 아이들이 인터넷으로 질 좋은 예술 교육을 접할 기회를 크게 늘렸다."],"ow":[[["老舍","Lǎo Shě","라오서(작가)"],["话剧","huàjù","연극"],["兴衰","xīngshuāi","흥망성쇠"],["折射","zhéshè","비추어 보이다"],["变迁","biànqiān","변천"]],[["海参","hǎishēn","해삼"],["夏眠","xiàmián","여름잠"],["潜伏","qiánfú","숨어 있다"],["礁石","jiāoshí","암초, 바위"]],[["洋山","Yángshān","양산(상하이의 항구)"],["集装箱","jízhuāngxiāng","컨테이너"],["码头","mǎtou","부두"],["桥吊","qiáodiào","안벽 크레인"],["调度","diàodù","운행을 지휘하다"]],[["远程","yuǎnchéng","원격"],["偏远","piānyuǎn","외지고 멀다"],["优质","yōuzhì","질 좋은"]]]},{"o":["梅兰芳在长期的舞台实践中，创造性地发展了京剧旦角的唱腔、念白、舞蹈和化妆，形成了雍容华贵、典雅大方的。","竹子虽然看起来像树，但在植物学上属于禾本科，与小麦、水稻是近亲。","由于海水对阳光中红光的吸收较强，蓝光则更容易被散射，所以大海看上去通常呈蓝色。","这份报告预测，未来十年全球对锂电池的需求将持续增长，原材料供应可能因此趋于紧张。"],"a":0,"type":"목적어 결여","why":"“形成了…的” 뒤에 명사가 없다. 무엇을 이루었는지(‘表演风格’)가 빠졌다.","fix":"梅兰芳在长期的舞台实践中，创造性地发展了京剧旦角的唱腔、念白、舞蹈和化妆，形成了雍容华贵、典雅大方的表演风格。","words":[["旦角","dànjué","(경극) 여자 배역"],["念白","niànbái","(희곡의) 대사"],["雍容华贵","yōng róng huá guì","의젓하고 화려하다"],["禾本科","héběnkē","벼과"],["散射","sǎnshè","산란하다"],["锂电池","lǐdiànchí","리튬 전지"],["趋于","qūyú","~로 기울다"]],"tr":["메이란팡은 오랜 무대 경험 속에서 경극 여자 배역의 창법·대사·춤·분장을 창의적으로 발전시켜 의젓하고 화려하며 우아한 연기 풍격을 이루었다.","대나무는 나무처럼 보이지만 식물학적으로는 벼과에 속하며 밀·벼와 가까운 친척이다.","바닷물은 햇빛 속 붉은빛을 많이 흡수하고 푸른빛은 더 쉽게 흩어지기 때문에 바다는 대개 푸르게 보인다.","이 보고서는 앞으로 10년간 세계의 리튬 전지 수요가 계속 늘어 원자재 공급이 빠듯해질 수 있다고 내다봤다."],"ow":[[["梅兰芳","Méi Lánfāng","메이란팡(경극 배우)"],["旦角","dànjué","(경극) 여자 배역"],["唱腔","chàngqiāng","창법, 노래 가락"],["念白","niànbái","대사"],["雍容华贵","yōngróng huáguì","의젓하고 화려하다"]],[["植物学","zhíwùxué","식물학"],["禾本科","héběnkē","벼과"],["近亲","jìnqīn","가까운 친척"]],[["吸收","xīshōu","흡수하다"],["散射","sǎnshè","산란하다"],["呈","chéng","(빛깔을) 띠다"]],[["预测","yùcè","예측하다"],["锂电池","lǐdiànchí","리튬 전지"],["原材料","yuáncáiliào","원자재"],["趋于","qūyú","~로 기울다"]]]},{"o":["作为一种古老的说唱艺术，苏州评弹用吴语表演，以其委婉动听的曲调深受江南百姓喜爱。","经过反复论证，专家们一致认为该项目具备了在生态环境脆弱的西北荒漠地区大规模推广的。","心理学家指出，人们往往会高估未来某件事给自己带来的情绪影响，这种现象被称为“影响偏差”。","贝多芬在双耳几乎完全失聪的情况下，依然创作出了气势恢宏的《第九交响曲》。"],"a":1,"type":"목적어 결여","why":"“具备了…推广的” 뒤에 명사가 없다. ‘具备’의 목적어 ‘条件’이 빠졌다.","fix":"经过反复论证，专家们一致认为该项目具备了在生态环境脆弱的西北荒漠地区大规模推广的条件。","words":[["评弹","píngtán","평탄(쑤저우 설창 예술)"],["委婉","wěiwǎn","완곡하고 부드럽다"],["论证","lùnzhèng","논증하다"],["脆弱","cuìruò","취약하다"],["失聪","shīcōng","청력을 잃다"],["恢宏","huīhóng","웅대하다"]],"tr":["오래된 설창 예술인 쑤저우 평탄은 우어로 공연하며, 부드럽고 듣기 좋은 가락으로 강남 사람들의 큰 사랑을 받는다.","거듭 검토한 끝에 전문가들은 이 사업이 생태가 취약한 서북 황무지 지역에서 대규모로 보급될 조건을 갖췄다고 입을 모았다.","심리학자들은 사람들이 앞으로 어떤 일이 자신에게 가져올 감정의 영향을 흔히 과대평가한다고 하며, 이를 '영향 편향'이라 부른다.","베토벤은 두 귀가 거의 완전히 들리지 않는 상황에서도 웅장한 『교향곡 9번』을 써냈다."],"ow":[[["说唱","shuōchàng","설창(말과 노래로 하는 공연)"],["评弹","píngtán","평탄(쑤저우 설창)"],["吴语","Wúyǔ","우어(쑤저우 일대 방언)"],["委婉","wěiwǎn","부드럽고 완곡하다"],["曲调","qǔdiào","가락"]],[["论证","lùnzhèng","논증하다"],["具备","jùbèi","갖추다"],["脆弱","cuìruò","취약하다"],["荒漠","huāngmò","황막한 사막"],["推广","tuīguǎng","널리 보급하다"]],[["高估","gāogū","과대평가하다"],["偏差","piānchā","편향, 편차"]],[["贝多芬","Bèiduōfēn","베토벤"],["失聪","shīcōng","청력을 잃다"],["恢宏","huīhóng","웅대하다"],["交响曲","jiāoxiǎngqǔ","교향곡"]]]}],[{"o":["京剧形成于清代中后期，由徽剧、汉剧等地方戏融合演变而来，至今已有两百多年的历史。","鄱阳湖每年冬季吸引数千只白鹤前来越冬，占全球白鹤总数的九成以上。","据统计，这位作家一生共创作了长篇小说十余部、短篇小说约三百篇左右，作品被译成了二十多种语言。","人类大脑的重量只占体重的百分之二左右，消耗的能量却占全身总能耗的约百分之二十。"],"a":2,"type":"어림수 중복","why":"“约三百篇左右”에서 ‘约’와 ‘左右’가 둘 다 어림수를 나타내 겹친다. 하나만 써야 한다.","fix":"据统计，这位作家一生共创作了长篇小说十余部、短篇小说三百篇左右，作品被译成了二十多种语言。","words":[["徽剧","huījù","휘극(안후이 지방극)"],["演变","yǎnbiàn","변천하다"],["鄱阳湖","Pó yáng hú","포양호"],["白鹤","báihè","시베리아흰두루미"],["越冬","yuèdōng","겨울을 나다"],["能耗","nénghào","에너지 소비"]],"tr":["경극은 청나라 중·후기에 형성되었으며 휘극·한극 같은 지방극이 융합하고 변해서 생겨났고, 지금까지 2백여 년의 역사를 지녔다.","포양호에는 해마다 겨울이면 수천 마리의 시베리아흰두루미가 겨울을 나러 오는데, 이는 전 세계 개체 수의 90% 이상이다.","통계에 따르면 이 작가는 평생 장편소설 10여 편과 단편소설 3백 편가량을 썼고, 작품은 20여 개 언어로 번역되었다.","사람 뇌의 무게는 체중의 2% 정도에 불과하지만, 쓰는 에너지는 몸 전체 소비량의 약 20%를 차지한다."],"ow":[[["京剧","jīngjù","경극"],["徽剧","huījù","휘극(안후이 지방극)"],["汉剧","hànjù","한극(후베이 지방극)"],["演变","yǎnbiàn","변천하다"]],[["鄱阳湖","Póyáng Hú","포양호"],["白鹤","báihè","시베리아흰두루미"],["越冬","yuèdōng","겨울을 나다"]],[["据统计","jù tǒngjì","통계에 따르면"],["长篇小说","chángpiān xiǎoshuō","장편소설"],["短篇小说","duǎnpiān xiǎoshuō","단편소설"]],[["大脑","dànǎo","대뇌"],["消耗","xiāohào","소모하다"],["能耗","nénghào","에너지 소비"]]]},{"o":["宋代瓷器以汝、官、哥、钧、定五大名窑最为著名，其中汝窑的传世品极为稀少。","这位小提琴家五岁开始学琴，十二岁便在国际比赛中崭露头角，被誉为“音乐神童”。","由于连续数月干旱少雨，当地水库的蓄水量比往年同期减少了将近一半。","这座始建于北魏时期的石窟寺，距今已有大约一千五百年上下的历史，是研究佛教艺术的重要实物资料。"],"a":3,"type":"어림수 중복","why":"“大约一千五百年上下”에서 ‘大约’와 ‘上下’가 같은 뜻으로 겹친다.","fix":"这座始建于北魏时期的石窟寺，距今已有大约一千五百年的历史，是研究佛教艺术的重要实物资料。","words":[["名窑","míngyáo","이름난 가마"],["传世品","chuánshìpǐn","대대로 전해 온 유물"],["崭露头角","zhǎn lù tóu jiǎo","두각을 나타내다"],["蓄水量","xùshuǐliàng","저수량"],["北魏","Běi Wèi","북위(왕조)"],["石窟","shíkū","석굴"]],"tr":["송나라 자기는 여요·관요·가요·균요·정요의 다섯 명요가 가장 유명하며, 그중 여요의 전해 오는 유물은 극히 드물다.","이 바이올리니스트는 다섯 살에 바이올린을 배우기 시작해 열두 살에 국제 대회에서 두각을 나타내 '음악 신동'으로 불렸다.","몇 달째 비가 거의 오지 않아 이 지역 저수지의 저수량은 예년 같은 때보다 거의 절반이나 줄었다.","북위 시대에 처음 세워진 이 석굴 사원은 약 1500년의 역사를 지녔으며 불교 미술을 연구하는 중요한 실물 자료다."],"ow":[[["瓷器","cíqì","자기"],["名窑","míngyáo","이름난 가마"],["汝窑","Rǔyáo","여요"],["传世品","chuánshìpǐn","대대로 전해 온 유물"],["稀少","xīshǎo","드물다"]],[["小提琴家","xiǎotíqínjiā","바이올리니스트"],["崭露头角","zhǎnlù tóujiǎo","두각을 나타내다"],["被誉为","bèi yùwéi","~로 칭송되다"],["神童","shéntóng","신동"]],[["干旱","gānhàn","가물다"],["水库","shuǐkù","저수지"],["蓄水量","xùshuǐliàng","저수량"],["同期","tóngqī","같은 시기"]],[["始建","shǐjiàn","처음 세우다"],["北魏","Běi Wèi","북위(왕조)"],["石窟","shíkū","석굴"],["佛教","fójiào","불교"]]]},{"o":["这位导演坦言，拍摄这部关于留守儿童的影片，其目的是为了唤起社会对乡村教育问题的关注。","甲骨文是目前发现的中国最早的成熟文字体系，主要刻写在龟甲和兽骨上，用于记录占卜内容。","不少鸟类在长途迁徙前会大量进食，以便在体内储存足够的脂肪来维持飞行所需的能量。","随着人口老龄化程度不断加深，养老服务的供需矛盾日益突出，亟待社会各方共同应对。"],"a":0,"type":"뜻 중복","why":"“目的是为了”에서 ‘目的’와 ‘为了’가 같은 뜻이라 겹친다. ‘为了’를 빼야 한다.","fix":"这位导演坦言，拍摄这部关于留守儿童的影片，其目的是唤起社会对乡村教育问题的关注。","words":[["坦言","tǎnyán","솔직히 말하다"],["留守儿童","liú shǒu ér tóng","(부모가 타지에 일하러 가) 남겨진 아이"],["唤起","huànqǐ","불러일으키다"],["甲骨文","jiǎgǔwén","갑골문"],["占卜","zhānbǔ","점치다"],["亟待","jídài","시급히 ~해야 한다"]],"tr":["이 감독은 남겨진 아이들을 다룬 이 영화를 찍은 목적이 농촌 교육 문제에 대한 사회의 관심을 불러일으키는 데 있다고 솔직히 말했다.","갑골문은 지금까지 발견된 중국 최초의 완성된 문자 체계로, 주로 거북 껍데기와 짐승 뼈에 새겨 점친 내용을 기록하는 데 썼다.","많은 새들은 먼 거리를 이동하기 전에 먹이를 많이 먹어, 비행에 필요한 에너지를 댈 만큼 몸속에 지방을 저장해 둔다.","인구 고령화가 갈수록 심해지면서 노인 돌봄 서비스의 수요와 공급 불균형이 두드러지고 있어, 사회 각계가 함께 대응하는 일이 시급하다."],"ow":[[["坦言","tǎnyán","솔직히 말하다"],["留守儿童","liúshǒu értóng","(부모가 떠나) 남겨진 아이"],["唤起","huànqǐ","불러일으키다"]],[["甲骨文","jiǎgǔwén","갑골문"],["龟甲","guījiǎ","거북 등딱지"],["兽骨","shòugǔ","짐승 뼈"],["占卜","zhānbǔ","점치다"]],[["迁徙","qiānxǐ","(철새 등이) 이동하다"],["储存","chǔcún","저장하다"],["脂肪","zhīfáng","지방"],["维持","wéichí","유지하다"]],[["老龄化","lǎolínghuà","고령화"],["供需","gōngxū","수요와 공급"],["矛盾","máodùn","모순, 갈등"],["亟待","jídài","시급히 ~해야 한다"]]]},{"o":["渔民号子是渔民在拉网、摇橹时为协调动作而唱的劳动歌，节奏铿锵有力，风格粗犷豪迈。","调查显示，东西部地区在人均拥有的剧场、美术馆等文化设施数量上，存在着十分悬殊的差别。","大熊猫的消化系统仍保留着食肉动物的特征，因此它们每天必须吃下大量竹子才能满足营养需求。","这种新研制的船用防污涂料虽然价格偏高，却能有效阻止藻类和贝类附着在船底。"],"a":1,"type":"뜻 중복","why":"‘悬殊’ 자체가 ‘차이가 크다’는 뜻이라 “悬殊的差别”는 뜻이 겹친다.","fix":"调查显示，东西部地区在人均拥有的剧场、美术馆等文化设施数量上，相差十分悬殊。","words":[["悬殊","xuánshū","차이가 매우 크다"],["消化","xiāohuà","소화하다"],["号子","hàozi","노동요"],["摇橹","yáolǔ","노를 젓다"],["铿锵","kēngqiāng","힘차게 울리다"],["粗犷","cūguǎng","거칠고 호방하다"],["涂料","túliào","도료"],["附着","fùzhuó","달라붙다"]],"tr":["어민 노동요는 어민들이 그물을 끌고 노를 저을 때 동작을 맞추려고 부르는 노래로, 박자가 힘차게 울리고 풍격이 거칠고 호방하다.","조사에 따르면 동부와 서부 지역은 1인당 극장·미술관 같은 문화 시설 수에서 차이가 매우 크다.","대왕판다의 소화 기관은 여전히 육식 동물의 특징을 지니고 있어서, 영양을 채우려면 날마다 대나무를 많이 먹어야 한다.","새로 개발된 이 선박용 방오 도료는 값이 좀 비싸지만 조류와 조개류가 배 밑바닥에 달라붙는 것을 효과적으로 막는다."],"ow":[[["号子","hàozi","노동요"],["摇橹","yáolǔ","노를 젓다"],["协调","xiétiáo","맞추다, 조화시키다"],["铿锵","kēngqiāng","힘차게 울리다"],["粗犷","cūguǎng","거칠고 호방하다"]],[["人均","rénjūn","1인당"],["设施","shèshī","시설"],["悬殊","xuánshū","차이가 매우 크다"]],[["消化","xiāohuà","소화하다"],["食肉动物","shíròu dòngwù","육식 동물"],["营养","yíngyǎng","영양"]],[["研制","yánzhì","연구 제작하다"],["涂料","túliào","도료"],["藻类","zǎolèi","조류(바닷말)"],["附着","fùzhuó","달라붙다"]]]},{"o":["汤显祖的《牡丹亭》讲述了杜丽娘与柳梦梅之间生死相恋的故事，被誉为明代传奇的巅峰之作。","这家公司之所以能在短短五年内跻身行业前列，主要是因为它始终把产品质量放在首位。","这部小说的结局处理得过于太仓促，许多读者认为人物的命运转折缺乏足够的铺垫。","地震发生后，救援队伍争分夺秒地展开搜救，在废墟中成功救出了数十名被困群众。"],"a":2,"type":"뜻 중복","why":"‘过于’와 ‘太’가 모두 ‘지나치게’라는 뜻이라 겹친다.","fix":"这部小说的结局处理得过于仓促，许多读者认为人物的命运转折缺乏足够的铺垫。","words":[["巅峰","diānfēng","정점, 최고봉"],["跻身","jīshēn","(대열에) 들어서다"],["仓促","cāngcù","촉박하다, 서두르다"],["铺垫","pūdiàn","복선, 사전 준비"],["争分夺秒","zhēng fēn duó miǎo","분초를 다투다"],["废墟","fèixū","폐허"]],"tr":["탕셴쭈의 『모란정』은 두려낭과 류멍메이의 생사를 넘나드는 사랑 이야기로, 명대 전기 희곡의 정점으로 꼽힌다.","이 회사가 불과 5년 만에 업계 선두권에 들 수 있었던 것은 주로 늘 제품 품질을 최우선으로 삼았기 때문이다.","이 소설의 결말은 지나치게 서둘러 처리되어, 많은 독자들은 인물의 운명이 바뀌는 데 충분한 복선이 없다고 생각한다.","지진이 난 뒤 구조대는 분초를 다투며 수색에 나서 폐허 속에서 갇힌 주민 수십 명을 구해 냈다."],"ow":[[["汤显祖","Tāng Xiǎnzǔ","탕셴쭈(명대 극작가)"],["牡丹亭","Mǔdān Tíng","모란정(희곡 제목)"],["传奇","chuánqí","전기(명대 장편 희곡)"],["巅峰","diānfēng","정점"]],[["跻身","jīshēn","(대열에) 들어서다"],["前列","qiánliè","앞줄, 선두"],["首位","shǒuwèi","첫째 자리"]],[["仓促","cāngcù","촉박하다"],["转折","zhuǎnzhé","전환"],["铺垫","pūdiàn","복선, 사전 준비"]],[["救援","jiùyuán","구조하다"],["争分夺秒","zhēng fēn duó miǎo","분초를 다투다"],["废墟","fèixū","폐허"],["被困","bèikùn","갇히다"]]]},{"o":["明代的《顺风相送》详细记载了远洋航行的针路和沿途岛屿，是研究古代航海史的珍贵文献。","这种深海鱼类能够自行发光，借此吸引猎物或在漆黑的海水中寻找同伴。","当代艺术展览越来越注重观众的参与和互动，许多作品甚至需要观众亲自操作才能完整呈现。","这家百年老戏院停业的原因，主要是长期缺乏资金进行维护的缘故。"],"a":3,"type":"뜻 중복","why":"‘原因’과 ‘缘故’가 같은 뜻이라 “原因…是…的缘故”는 겹친다.","fix":"这家百年老戏院停业的原因，主要是长期缺乏资金进行维护。","words":[["猎物","lièwù","사냥감"],["漆黑","qīhēi","칠흑같이 어둡다"],["呈现","chéngxiàn","드러내다, 나타내다"],["缘故","yuángù","까닭"],["针路","zhēnlù","나침반 항로"],["文献","wénxiàn","문헌"]],"tr":["명나라 때의 『순풍상송』은 원양 항해의 나침반 항로와 지나는 섬들을 자세히 적은 책으로, 고대 항해사를 연구하는 귀한 문헌이다.","이 심해 물고기는 스스로 빛을 낼 수 있어, 그것으로 먹잇감을 꾀거나 캄캄한 바닷속에서 짝을 찾는다.","요즘 현대 미술 전시는 관객의 참여와 상호 작용을 갈수록 중시해, 많은 작품은 관객이 직접 조작해야 온전히 드러난다.","이 백 년 된 옛 극장이 문을 닫은 원인은 주로 오랫동안 보수할 자금이 없었기 때문이다."],"ow":[[["顺风相送","Shùnfēng Xiāngsòng","순풍상송(항해서 이름)"],["远洋","yuǎnyáng","원양"],["针路","zhēnlù","나침반 항로"],["航海","hánghǎi","항해"],["文献","wénxiàn","문헌"]],[["深海","shēnhǎi","심해"],["借此","jiècǐ","이를 이용해"],["猎物","lièwù","사냥감"],["漆黑","qīhēi","칠흑같이 어둡다"]],[["当代","dāngdài","현대"],["注重","zhùzhòng","중시하다"],["互动","hùdòng","상호 작용"],["呈现","chéngxiàn","드러내다"]],[["戏院","xìyuàn","극장"],["停业","tíngyè","영업을 멈추다"],["维护","wéihù","유지 보수하다"],["缘故","yuángù","까닭"]]]},{"o":["凡是到过西湖的游客，无不都为那里“淡妆浓抹总相宜”的湖光山色所倾倒。","这部电影虽然投资不大，却因为真实细腻的情感表达而获得了观众的广泛共鸣。","疍家人世代以船为家、以渔为业，在珠江口一带形成了独具特色的水上婚俗和咸水歌。","专家建议，老年人锻炼应量力而行，切忌盲目追求运动强度。"],"a":0,"type":"군더더기","why":"‘无不’가 이미 ‘모두 ~하다’는 뜻이라 뒤의 ‘都’가 남는다.","fix":"凡是到过西湖的游客，无不为那里“淡妆浓抹总相宜”的湖光山色所倾倒。","words":[["无不","wúbù","~하지 않는 것이 없다"],["淡妆浓抹","dàn zhuāng nóng mǒ","옅은 화장과 짙은 화장"],["倾倒","qīngdǎo","매료되다"],["共鸣","gòngmíng","공감"],["量力而行","liàng lì ér xíng","힘에 맞게 하다"],["切忌","qièjì","절대 삼가다"],["疍家","Dàn jiā","단자(배 위에 사는 사람들)"],["咸水歌","xiánshuǐgē","단자 사람들의 민요"]],"tr":["시후에 가 본 관광객이라면 누구나 '옅은 화장도 짙은 화장도 다 어울린다'는 그곳의 호수와 산 경치에 반하지 않은 이가 없다.","이 영화는 투자 규모가 크지 않았지만 진솔하고 섬세한 감정 표현으로 관객의 폭넓은 공감을 얻었다.","단자 사람들은 대대로 배를 집 삼고 고기잡이를 생업으로 하며, 주장 하구 일대에서 독특한 수상 혼례 풍습과 함수가를 이루었다.","전문가들은 노인이 운동할 때 자기 힘에 맞게 해야 하며, 무작정 운동 강도를 높이는 것은 절대 피해야 한다고 조언한다."],"ow":[[["凡是","fánshì","무릇, 모든"],["无不","wúbù","~하지 않는 것이 없다"],["淡妆浓抹","dàn zhuāng nóng mǒ","옅은 화장과 짙은 화장"],["倾倒","qīngdǎo","매료되다"]],[["投资","tóuzī","투자"],["细腻","xìnì","섬세하다"],["共鸣","gòngmíng","공감"]],[["疍家","Dànjiā","단자(배 위에 사는 사람들)"],["世代","shìdài","대대로"],["珠江口","Zhūjiāng Kǒu","주장 하구"],["婚俗","hūnsú","혼례 풍습"],["咸水歌","xiánshuǐgē","함수가(단자 민요)"]],[["量力而行","liàng lì ér xíng","힘에 맞게 하다"],["切忌","qièjì","절대 삼가다"],["盲目","mángmù","맹목적이다"],["强度","qiángdù","강도"]]]},{"o":["宋代的《清明上河图》以长卷形式描绘了北宋都城汴京的繁华景象，具有极高的历史和艺术价值。","在长达一个月的交流活动中，中法两国的青年画家彼此互相切磋技艺，共同完成了一幅长达三十米的长卷。","退耕还林政策实施以来，这一地区的水土流失状况得到了明显改善。","人们常说“读万卷书，行万里路”，强调的正是书本知识与实践经验相结合的重要性。"],"a":1,"type":"군더더기","why":"‘彼此’와 ‘互相’이 같은 뜻이라 하나는 빼야 한다.","fix":"在长达一个月的交流活动中，中法两国的青年画家互相切磋技艺，共同完成了一幅长达三十米的长卷。","words":[["汴京","Biàn jīng","볜징(북송 수도, 지금의 카이펑)"],["长卷","chángjuàn","두루마리 그림"],["切磋","qiēcuō","서로 갈고닦다"],["退耕还林","tuì gēng huán lín","경작지를 숲으로 되돌리다"],["水土流失","shuǐ tǔ liú shī","토양 유실"]],"tr":["송대의 『청명상하도』는 두루마리 형식으로 북송 수도 볜징의 번화한 모습을 그려 역사적·예술적 가치가 매우 높다.","한 달에 걸친 교류 행사에서 중국과 프랑스의 젊은 화가들은 서로 기량을 갈고닦으며 30미터 길이의 두루마리 그림을 함께 완성했다.","경작지를 숲으로 되돌리는 정책이 시행된 뒤로 이 지역의 토양 유실은 눈에 띄게 나아졌다.","흔히 '만 권의 책을 읽고 만 리 길을 걸으라'고 하는데, 이 말이 강조하는 것은 바로 책의 지식과 실제 경험을 함께 갖추는 일의 중요성이다."],"ow":[[["清明上河图","Qīngmíng Shàng Hé Tú","청명상하도"],["长卷","chángjuàn","두루마리 그림"],["汴京","Biànjīng","볜징(북송 수도)"],["繁华","fánhuá","번화하다"]],[["彼此","bǐcǐ","서로"],["切磋","qiēcuō","서로 갈고닦다"],["技艺","jìyì","기예"],["长卷","chángjuàn","두루마리 그림"]],[["退耕还林","tuì gēng huán lín","경작지를 숲으로 되돌리다"],["实施","shíshī","실시하다"],["水土流失","shuǐtǔ liúshī","토양 유실"]],[["万卷","wànjuàn","만 권"],["强调","qiángdiào","강조하다"],["相结合","xiāng jiéhé","서로 결합하다"]]]},{"o":["越窑青瓷釉色青翠莹润，唐代诗人陆龟蒙曾以“九秋风露越窑开，夺得千峰翠色来”加以赞美。","这项研究成果一经发表，便在国际学术界引起了强烈反响。","这位青年学者近日发表了一篇关于对唐代边塞诗中的地理意象进行系统考察的论文，引起了学界关注。","太阳能、风能等清洁能源的利用比例逐年上升，但储能技术仍是制约其发展的瓶颈。"],"a":2,"type":"군더더기","why":"“关于对…”에서 개사 ‘关于’와 ‘对’가 겹쳐 쓰였다. ‘关于’를 빼야 한다.","fix":"这位青年学者近日发表了一篇对唐代边塞诗中的地理意象进行系统考察的论文，引起了学界关注。","words":[["釉色","yòusè","유약 빛깔"],["莹润","yíngrùn","맑고 윤기 있다"],["反响","fǎnxiǎng","반향"],["边塞诗","biānsàishī","변새시(변방을 읊은 시)"],["意象","yìxiàng","(시의) 이미지"],["制约","zhìyuē","제약하다"],["瓶颈","píngjǐng","병목"]],"tr":["월요 청자는 유약 빛깔이 푸르고 맑고 윤기 있어, 당나라 시인 육구몽은 '늦가을 바람과 이슬 속에 월요가 열리니, 천 봉우리의 푸른빛을 빼앗아 왔네'라고 기렸다.","이 연구 성과는 발표되자마자 국제 학계에서 큰 반향을 일으켰다.","이 젊은 학자는 최근 당대 변새시에 나타난 지리적 이미지를 체계적으로 살핀 논문을 발표해 학계의 주목을 받았다.","태양광·풍력 같은 청정 에너지의 이용 비율은 해마다 높아지고 있지만, 에너지 저장 기술은 여전히 그 발전을 가로막는 병목이다."],"ow":[[["越窑","Yuèyáo","월요(저장의 청자 가마)"],["青瓷","qīngcí","청자"],["釉色","yòusè","유약 빛깔"],["莹润","yíngrùn","맑고 윤기 있다"],["陆龟蒙","Lù Guīméng","육구몽(당대 시인)"]],[["一经","yìjīng","~하자마자"],["学术界","xuéshùjiè","학계"],["反响","fǎnxiǎng","반향"]],[["学者","xuézhě","학자"],["边塞诗","biānsàishī","변새시(변방을 읊은 시)"],["意象","yìxiàng","(시의) 이미지"],["考察","kǎochá","고찰하다"]],[["清洁能源","qīngjié néngyuán","청정 에너지"],["储能","chǔnéng","에너지 저장"],["制约","zhìyuē","제약하다"],["瓶颈","píngjǐng","병목"]]]},{"o":["柳宗元的《江雪》仅用二十个字，便勾勒出一幅孤寂清冷的寒江独钓图。","这家博物馆不得不暂时闭馆，因为馆内的空调和消防系统需要全面检修。","海拔越高，空气越稀薄，人体在高原上剧烈运动容易出现缺氧症状。","凡是参加此次书法大赛的作品，都必须全部是参赛者本人近两年内创作的原作。"],"a":3,"type":"군더더기","why":"‘凡是…都’로 이미 ‘모두’를 말했는데 ‘全部’를 또 써서 겹친다.","fix":"凡是参加此次书法大赛的作品，都必须是参赛者本人近两年内创作的原作。","words":[["勾勒","gōulè","윤곽을 그리다"],["孤寂","gūjì","외롭고 쓸쓸하다"],["检修","jiǎnxiū","점검 수리하다"],["稀薄","xībó","희박하다"],["缺氧","quēyǎng","산소 결핍"],["原作","yuánzuò","원작"]],"tr":["류종원의 『강설』은 고작 스무 글자로 외롭고 차가운 겨울 강에서 홀로 낚시하는 그림을 그려 냈다.","이 박물관은 관 안의 냉방과 소방 시스템을 전면 점검·수리해야 해서 어쩔 수 없이 잠시 문을 닫았다.","해발이 높을수록 공기가 희박해져서, 고원에서 격렬하게 운동하면 산소 부족 증상이 나타나기 쉽다.","이번 서예 대회에 출품하는 작품은 모두 참가자 본인이 최근 2년 안에 쓴 원작이어야 한다."],"ow":[[["柳宗元","Liǔ Zōngyuán","류종원(당대 문인)"],["勾勒","gōulè","윤곽을 그리다"],["孤寂","gūjì","외롭고 쓸쓸하다"],["清冷","qīnglěng","싸늘하다"]],[["不得不","bùdébù","어쩔 수 없이"],["消防","xiāofáng","소방"],["检修","jiǎnxiū","점검 수리하다"]],[["海拔","hǎibá","해발"],["稀薄","xībó","희박하다"],["剧烈","jùliè","격렬하다"],["缺氧","quēyǎng","산소 결핍"]],[["凡是","fánshì","무릇, 모든"],["参赛者","cānsàizhě","참가자"],["原作","yuánzuò","원작"]]]}],[{"o":["草书讲究笔势的连贯与气韵的流动，唐代的张旭和怀素都是这一书体的代表人物。","近年来，这座城市通过修复历史街区、兴建文化场馆，大大提高了市民的文化生活。","鲸鱼虽然生活在海洋里，却和人类一样用肺呼吸，属于哺乳动物。","面对突如其来的金融危机，许多中小企业不得不压缩开支、裁减人员以渡过难关。"],"a":1,"type":"동사–목적어","why":"‘提高’는 ‘文化生活’와 어울리지 않는다. ‘丰富…文化生活’나 ‘提高…文化生活水平’이라고 해야 한다.","fix":"近年来，这座城市通过修复历史街区、兴建文化场馆，大大丰富了市民的文化生活。","words":[["草书","cǎoshū","초서"],["笔势","bǐshì","붓의 기세"],["气韵","qìyùn","기운과 운치"],["哺乳动物","bǔ rǔ dòng wù","포유동물"],["突如其来","tū rú qí lái","갑자기 닥치다"],["压缩","yāsuō","줄이다"],["裁减","cáijiǎn","감원하다"]],"tr":["초서는 붓 기세의 이어짐과 기운의 흐름을 중시하며, 당나라의 장욱과 회소가 이 서체를 대표하는 인물이다.","최근 몇 년 동안 이 도시는 역사 거리를 복원하고 문화 시설을 새로 지어 시민들의 문화생활을 크게 풍요롭게 했다.","고래는 바다에 살지만 사람처럼 폐로 숨을 쉬는 포유동물이다.","갑자기 닥친 금융 위기 앞에서 많은 중소기업은 어쩔 수 없이 지출을 줄이고 인원을 감축해 어려움을 넘겼다."],"ow":[[["草书","cǎoshū","초서"],["笔势","bǐshì","붓의 기세"],["连贯","liánguàn","이어지다"],["气韵","qìyùn","기운과 운치"],["张旭","Zhāng Xù","장욱(당대 서예가)"],["怀素","Huáisù","회소(당대 승려 서예가)"]],[["修复","xiūfù","복원하다"],["街区","jiēqū","거리, 구역"],["兴建","xīngjiàn","세우다"],["场馆","chǎngguǎn","시설, 관"]],[["鲸鱼","jīngyú","고래"],["肺","fèi","폐"],["哺乳动物","bǔrǔ dòngwù","포유동물"]],[["突如其来","tū rú qí lái","갑자기 닥치다"],["压缩","yāsuō","줄이다"],["开支","kāizhī","지출"],["裁减","cáijiǎn","감원하다"],["渡过难关","dùguò nánguān","난관을 넘기다"]]]},{"o":["《二泉映月》是民间艺人阿炳创作的二胡名曲，曲调凄婉动人，饱含着作者对坎坷人生的感慨。","研究人员利用卫星遥感技术，对这片原始森林的植被覆盖情况进行了长期监测。","这部电视剧播出后，在社会上掀起了一股学习传统文化的热潮，也端正了不少年轻人对传统艺术的偏见。","不少城市开始在地铁站和公园里设置自助借书机，让市民随时随地都能借阅图书。"],"a":2,"type":"동사–목적어","why":"‘端正’은 ‘态度’와 어울리고 ‘偏见’과는 어울리지 않는다. 편견은 ‘消除’한다.","fix":"这部电视剧播出后，在社会上掀起了一股学习传统文化的热潮，也消除了不少年轻人对传统艺术的偏见。","words":[["凄婉","qīwǎn","구슬프고 애절하다"],["坎坷","kǎnkě","순탄치 못하다"],["遥感","yáogǎn","원격 탐사"],["植被","zhíbèi","식생"],["掀起","xiānqǐ","불러일으키다"],["端正","duānzhèng","바로잡다"],["偏见","piānjiàn","편견"]],"tr":["『이천영월』은 민간 예인 아빙이 지은 얼후 명곡으로, 가락이 구슬프고 애절하며 순탄치 못한 삶에 대한 작곡자의 감회가 가득 담겨 있다.","연구진은 위성 원격 탐사 기술로 이 원시림의 식생 분포를 오랫동안 관측했다.","이 드라마가 방영된 뒤 사회에 전통문화를 배우는 열풍이 일었고, 전통 예술에 대한 많은 젊은이들의 편견도 사라졌다.","많은 도시가 지하철역과 공원에 무인 도서 대출기를 두기 시작해, 시민들이 언제 어디서나 책을 빌릴 수 있게 했다."],"ow":[[["二泉映月","Èrquán Yìng Yuè","이천영월(곡 이름)"],["阿炳","Ā Bǐng","아빙(민간 음악가)"],["二胡","èrhú","얼후"],["凄婉","qīwǎn","구슬프고 애절하다"],["坎坷","kǎnkě","순탄치 못하다"],["感慨","gǎnkǎi","감개"]],[["遥感","yáogǎn","원격 탐사"],["原始森林","yuánshǐ sēnlín","원시림"],["植被","zhíbèi","식생"],["监测","jiāncè","모니터링하다"]],[["掀起","xiānqǐ","불러일으키다"],["热潮","rècháo","열풍"],["端正","duānzhèng","바로잡다"],["偏见","piānjiàn","편견"]],[["设置","shèzhì","설치하다"],["自助","zìzhù","셀프, 무인"],["随时随地","suíshí suídì","언제 어디서나"],["借阅","jièyuè","빌려 읽다"]]]},{"o":["青岛的老城区依山傍海，红瓦绿树、碧海蓝天的城市风貌吸引了许多画家前来写生。","长期饮用含氟量过高的地下水，会导致牙齿和骨骼出现病变。","这项政策实施三年来，农村居民的人均可支配收入增长了近一倍。","心理学家建议，家长应从小注意让孩子养成独立思考和解决问题的能力，而不是事事包办。"],"a":3,"type":"동사–목적어","why":"‘养成’은 ‘习惯’과 어울리고 ‘能力’와는 어울리지 않는다. 능력은 ‘培养’한다.","fix":"心理学家建议，家长应从小注意培养孩子独立思考和解决问题的能力，而不是事事包办。","words":[["含氟量","hánfúliàng","불소 함량"],["病变","bìngbiàn","병적 변화"],["可支配收入","kě zhī pèi shōu rù","가처분 소득"],["包办","bāobàn","도맡아 처리하다"],["依山傍海","yī shān bàng hǎi","산을 끼고 바다에 닿아 있다"],["写生","xiěshēng","사생하다"]],"tr":["칭다오의 옛 시가지는 산을 끼고 바다에 닿아 있어, 붉은 기와와 푸른 나무, 파란 바다와 하늘이 어우러진 도시 풍경이 많은 화가를 사생하러 오게 했다.","불소가 너무 많이 든 지하수를 오래 마시면 이와 뼈에 병이 생길 수 있다.","이 정책이 시행된 지 3년 동안 농촌 주민의 1인당 가처분 소득은 거의 두 배로 늘었다.","심리학자들은 부모가 아이에게 어려서부터 스스로 생각하고 문제를 해결하는 능력을 길러 주어야 하며, 모든 일을 대신해 주어서는 안 된다고 조언한다."],"ow":[[["青岛","Qīngdǎo","칭다오"],["依山傍海","yī shān bàng hǎi","산을 끼고 바다에 닿아 있다"],["风貌","fēngmào","모습, 풍모"],["写生","xiěshēng","사생하다"]],[["含氟量","hánfúliàng","불소 함량"],["骨骼","gǔgé","뼈"],["病变","bìngbiàn","병적 변화"]],[["实施","shíshī","시행하다"],["人均","rénjūn","1인당"],["可支配收入","kě zhīpèi shōurù","가처분 소득"]],[["独立","dúlì","독립적이다"],["包办","bāobàn","도맡아 처리하다"]]]},{"o":["每到金秋时节，香山的红叶就游人如织，前来观赏的市民和游客往往要排队数小时才能登上山顶。","每逢冬季风浪大的时节，码头上的老渔民便忙着修补渔网、检修柴油机，为开春后出海做准备。","尽管这种新药在动物实验中效果显著，但其对人体的安全性仍有待进一步验证。","这位民营企业家把多年积攒的财富投入到家乡的教育事业中，资助了上千名贫困学生。"],"a":0,"type":"주어–술어","why":"주어 ‘红叶’와 술어 ‘游人如织’가 맞지 않는다. 사람이 붐비는 곳은 단풍이 아니라 ‘香山’이다.","fix":"每到金秋时节，香山就游人如织，前来观赏红叶的市民和游客往往要排队数小时才能登上山顶。","words":[["游人如织","yóu rén rú zhī","관광객이 붐비다"],["显著","xiǎnzhù","뚜렷하다"],["有待","yǒudài","~할 필요가 있다"],["积攒","jīzǎn","모으다"],["修补","xiūbǔ","수선하다"],["柴油机","cháiyóujī","디젤 엔진"]],"tr":["가을이 무르익을 때마다 샹산은 단풍 구경 인파로 붐벼, 시민과 관광객들은 몇 시간씩 줄을 서야 산꼭대기에 오를 수 있다.","겨울 풍랑이 거센 철이면 부두의 늙은 어부들은 그물을 깁고 디젤 엔진을 손보느라 바쁘게 봄 출어를 준비한다.","이 신약은 동물 실험에서 뚜렷한 효과를 보였지만, 사람에게 안전한지는 아직 더 검증해야 한다.","이 민간 기업가는 여러 해 모은 재산을 고향의 교육 사업에 쏟아 가난한 학생 천여 명을 도왔다."],"ow":[[["金秋","jīnqiū","황금빛 가을"],["香山","Xiāngshān","샹산(베이징의 산)"],["游人如织","yóurén rú zhī","관광객이 붐비다"],["观赏","guānshǎng","감상하다"]],[["每逢","měiféng","~때마다"],["码头","mǎtou","부두"],["修补","xiūbǔ","수선하다"],["检修","jiǎnxiū","점검 수리하다"],["柴油机","cháiyóujī","디젤 엔진"]],[["显著","xiǎnzhù","뚜렷하다"],["有待","yǒudài","~할 필요가 있다"],["验证","yànzhèng","검증하다"]],[["民营","mínyíng","민간 경영"],["积攒","jīzǎn","모으다"],["资助","zīzhù","재정적으로 돕다"],["贫困","pínkùn","빈곤하다"]]]},{"o":["傅雷翻译的巴尔扎克小说语言流畅传神，被认为是翻译文学中的典范之作。","受强冷空气影响，这几天北方大部分地区的气温骤然寒冷，最低气温普遍降到了零下十摄氏度以下。","一海里约合一千八百五十二米，这一长度单位至今仍在航海和航空领域普遍使用。","我们不能因为一时的挫折就怀疑自己的能力，更不能轻易放弃已经坚持了多年的理想。"],"a":1,"type":"주어–술어","why":"‘气温’은 ‘寒冷’할 수 없다. 기온은 ‘骤降(떨어지다)’하고, 추워지는 것은 ‘天气’다.","fix":"受强冷空气影响，这几天北方大部分地区的天气骤然寒冷，最低气温普遍降到了零下十摄氏度以下。","words":[["传神","chuánshén","생생하게 묘사하다"],["典范","diǎnfàn","모범"],["骤然","zhòurán","갑자기"],["挫折","cuòzhé","좌절"],["海里","hǎilǐ","해리"],["约合","yuēhé","대략 ~에 해당하다"]],"tr":["푸레이가 번역한 발자크 소설은 문장이 매끄럽고 생동감이 있어 번역 문학의 모범으로 꼽힌다.","강한 한파의 영향으로 요 며칠 북방 대부분 지역의 날씨가 갑자기 추워져, 최저 기온이 대체로 영하 10도 아래로 떨어졌다.","1해리는 약 1852미터에 해당하며, 이 길이 단위는 지금도 항해와 항공 분야에서 널리 쓰인다.","한때의 좌절 때문에 자기 능력을 의심해서는 안 되며, 여러 해 지켜 온 꿈을 쉽게 포기해서는 더더욱 안 된다."],"ow":[[["傅雷","Fù Léi","푸레이(번역가)"],["巴尔扎克","Bā'ěrzhākè","발자크"],["传神","chuánshén","생생하게 묘사하다"],["典范","diǎnfàn","모범"]],[["骤然","zhòurán","갑자기"],["寒冷","hánlěng","춥다"],["摄氏度","shèshìdù","섭씨 온도"]],[["海里","hǎilǐ","해리"],["约合","yuēhé","대략 ~에 해당하다"],["航海","hánghǎi","항해"],["航空","hángkōng","항공"]],[["挫折","cuòzhé","좌절"],["怀疑","huáiyí","의심하다"],["轻易","qīngyì","쉽게, 함부로"]]]},{"o":["二十四节气是中国古人根据太阳在黄道上的位置划分出来的，用来指导农事活动。","这位指挥家与乐团合作多年，彼此之间早已形成了一种无需言语的默契。","诗人杜甫的故里是河南巩义人，他一生忧国忧民，被后世尊为“诗圣”。","鳗鲡是一种奇特的洄游鱼类，它们在淡水中生长，却要游到遥远的深海中去产卵。"],"a":2,"type":"주어–목적어","why":"“故里是…人”은 ‘고향은 ~사람이다’가 되어 주어와 목적어가 맞지 않는다.","fix":"诗人杜甫是河南巩义人，他一生忧国忧民，被后世尊为“诗圣”。","words":[["节气","jiéqi","절기"],["黄道","huángdào","황도"],["默契","mòqì","암묵적 호흡"],["故里","gùlǐ","고향"],["巩义","Gǒng yì","궁이(허난성의 도시)"],["鳗鲡","mánlí","뱀장어"],["洄游","huíyóu","회유하다"],["产卵","chǎnluǎn","알을 낳다"]],"tr":["24절기는 옛 중국 사람들이 황도 위 태양의 위치에 따라 나눈 것으로, 농사일을 이끄는 데 쓰였다.","이 지휘자는 오케스트라와 여러 해 함께해, 서로 말하지 않아도 통하는 호흡이 이미 생겼다.","시인 두보는 허난 궁이 사람으로, 평생 나라와 백성을 걱정해 후세에 '시성'으로 받들어졌다.","뱀장어는 특이한 회유 어류로, 민물에서 자라지만 알을 낳으러 머나먼 심해까지 헤엄쳐 간다."],"ow":[[["节气","jiéqi","절기"],["黄道","huángdào","황도"],["划分","huàfēn","나누다"],["农事","nóngshì","농사일"]],[["指挥家","zhǐhuījiā","지휘자"],["乐团","yuètuán","악단"],["无需","wúxū","~할 필요 없다"],["默契","mòqì","암묵적 호흡"]],[["杜甫","Dù Fǔ","두보"],["故里","gùlǐ","고향"],["巩义","Gǒngyì","궁이(허난성의 도시)"],["忧国忧民","yōu guó yōu mín","나라와 백성을 걱정하다"],["诗圣","shīshèng","시성"]],[["鳗鲡","mánlí","뱀장어"],["奇特","qítè","특이하다"],["洄游","huíyóu","회유하다"],["淡水","dànshuǐ","민물"],["产卵","chǎnluǎn","알을 낳다"]]]},{"o":["昆虫的复眼由成千上万个小眼组成，因此对运动物体的察觉非常敏锐。","林语堂用英文写成的《京华烟云》，向西方读者展示了二十世纪初中国社会的风貌。","为了保护古城墙免受进一步破坏，当地已禁止重型车辆在城墙周边行驶。","这次演出取得成功的关键，是全体演员和舞美、灯光等幕后工作人员数月来日夜辛勤排练的结果。"],"a":3,"type":"주어–목적어","why":"“关键是…的结果”는 ‘관건이 결과다’가 되어 맞지 않는다. ‘关键’을 빼고 ‘演出取得成功，是…的结果’로 해야 한다.","fix":"这次演出取得成功，是全体演员和舞美、灯光等幕后工作人员数月来日夜辛勤排练的结果。","words":[["复眼","fùyǎn","겹눈"],["敏锐","mǐnruì","예민하다"],["风貌","fēngmào","모습, 풍모"],["舞美","wǔměi","무대 미술"],["幕后","mùhòu","무대 뒤"],["排练","páiliàn","리허설하다"]],"tr":["곤충의 겹눈은 수많은 낱눈으로 이루어져 있어 움직이는 물체를 아주 예민하게 알아챈다.","린위탕이 영어로 쓴 『경화연운』은 서양 독자들에게 20세기 초 중국 사회의 모습을 보여 주었다.","옛 성벽이 더 이상 훼손되지 않도록 이 지역은 성벽 주변에서 대형 차량의 운행을 금지했다.","이번 공연의 성공은 모든 배우와 무대 미술·조명 등 무대 뒤 스태프들이 몇 달 동안 밤낮으로 열심히 연습한 결과다."],"ow":[[["复眼","fùyǎn","겹눈"],["成千上万","chéng qiān shàng wàn","수천수만"],["察觉","chájué","알아차리다"],["敏锐","mǐnruì","예민하다"]],[["林语堂","Lín Yǔtáng","린위탕(작가)"],["京华烟云","Jīnghuá Yānyún","경화연운(소설 제목)"],["风貌","fēngmào","모습, 풍모"]],[["免受","miǎnshòu","~을 면하다"],["禁止","jìnzhǐ","금지하다"],["重型","zhòngxíng","대형, 중량급"]],[["舞美","wǔměi","무대 미술"],["幕后","mùhòu","무대 뒤"],["辛勤","xīnqín","부지런하다"],["排练","páiliàn","리허설하다"]]]},{"o":["能否深入理解作品所处的历史背景，是读懂一部古典小说的重要前提。","熊猫幼崽刚出生时体重只有一百克左右，仅为母体的千分之一。","这家博物馆近年来推出的文创产品，因设计新颖、实用性强而颇受年轻人追捧。","尽管当时的生活极其清贫，曹雪芹仍以惊人的毅力完成了《红楼梦》前八十回的创作。"],"a":0,"type":"양면–한면","why":"앞의 ‘能否(할 수 있는지 없는지)’는 두 면인데 뒤의 ‘重要前提’는 한 면이라 맞지 않는다. ‘能否’를 빼야 한다.","fix":"深入理解作品所处的历史背景，是读懂一部古典小说的重要前提。","words":[["前提","qiántí","전제"],["幼崽","yòuzǎi","새끼"],["文创","wénchuàng","문화 창의(상품)"],["追捧","zhuīpěng","열광하다"],["清贫","qīngpín","청빈하다"],["毅力","yìlì","굳센 의지"]],"tr":["작품이 놓인 역사적 배경을 깊이 이해하는 것은 고전 소설 한 편을 제대로 읽어 내는 중요한 전제다.","판다 새끼는 갓 태어났을 때 몸무게가 100그램 안팎으로, 어미의 천분의 일에 불과하다.","이 박물관이 최근 내놓은 문화 상품들은 디자인이 참신하고 실용적이어서 젊은이들에게 큰 인기를 얻고 있다.","당시 생활은 몹시 가난했지만 조설근은 놀라운 의지로 『홍루몽』 앞 80회를 완성했다."],"ow":[[["能否","néngfǒu","~할 수 있는지"],["背景","bèijǐng","배경"],["前提","qiántí","전제"]],[["幼崽","yòuzǎi","새끼"],["母体","mǔtǐ","어미 몸"]],[["文创","wénchuàng","문화 창의(상품)"],["新颖","xīnyǐng","참신하다"],["颇","pō","꽤"],["追捧","zhuīpěng","열광하다"]],[["清贫","qīngpín","청빈하다"],["曹雪芹","Cáo Xuěqín","조설근(작가)"],["毅力","yìlì","굳센 의지"],["红楼梦","Hónglóu Mèng","홍루몽"]]]},{"o":["杭州西湖文化景观于2011年被列入《世界遗产名录》，“断桥残雪”“三潭印月”等景致早已闻名遐迩。","演员台词功底的好坏，是一部话剧能够打动观众的关键因素。","大气中二氧化碳浓度的持续升高，被普遍认为是全球气候变暖的主要原因之一。","这位老中医行医五十余年，对许多疑难杂症都有独到的见解。"],"a":1,"type":"양면–한면","why":"앞의 ‘好坏’는 두 면인데 뒤의 ‘能够打动观众’은 한 면이라 맞지 않는다.","fix":"演员台词功底扎实，是一部话剧能够打动观众的关键因素。","words":[["景致","jǐngzhì","경치"],["闻名遐迩","wén míng xiá ěr","널리 이름나다"],["台词","táicí","대사"],["功底","gōngdǐ","기본기"],["浓度","nóngdù","농도"],["疑难杂症","yí nán zá zhèng","난치병"]],"tr":["항저우 시후 문화 경관은 2011년 『세계유산목록』에 올랐으며, '단교잔설'·'삼담인월' 같은 경치는 일찍부터 널리 이름났다.","배우의 대사 기본기가 탄탄한 것은 연극이 관객을 감동시키는 핵심 요소다.","대기 중 이산화탄소 농도가 계속 높아지는 것은 지구 온난화의 주요 원인 가운데 하나로 널리 여겨진다.","이 노한의사는 50여 년 동안 진료하며 여러 난치병에 대해 남다른 견해를 지니고 있다."],"ow":[[["景观","jǐngguān","경관"],["名录","mínglù","목록"],["景致","jǐngzhì","경치"],["闻名遐迩","wénmíng xiá'ěr","널리 이름나다"]],[["台词","táicí","대사"],["功底","gōngdǐ","기본기"],["话剧","huàjù","연극"],["打动","dǎdòng","감동시키다"]],[["二氧化碳","èryǎnghuàtàn","이산화탄소"],["浓度","nóngdù","농도"],["气候变暖","qìhòu biànnuǎn","기후 온난화"]],[["中医","zhōngyī","한의사"],["行医","xíngyī","의술을 행하다"],["疑难杂症","yínán zázhèng","난치병"],["独到","dúdào","독창적이다"],["见解","jiànjiě","견해"]]]},{"o":["《三国演义》塑造了诸葛亮、关羽、曹操等一系列个性鲜明的人物形象。","由于海水的比热容较大，沿海城市的昼夜温差通常比内陆城市小得多。","为了提高学生的审美素养，学校邀请了几位知名画家来校举办讲座，并展出了他们近年来创作的作品和艺术心得。","他在退休后潜心研究地方戏曲史，先后出版了三部颇有分量的学术专著。"],"a":2,"type":"목적어 일부 호응","why":"‘展出’는 ‘作品’과는 어울리지만 ‘艺术心得(깨달음)’는 전시할 수 없다.","fix":"为了提高学生的审美素养，学校邀请了几位知名画家来校举办讲座，分享艺术心得，并展出了他们近年来创作的作品。","words":[["塑造","sùzào","(인물을) 형상화하다"],["审美","shěnměi","심미"],["素养","sùyǎng","소양"],["心得","xīndé","깨달은 바"],["潜心","qiánxīn","몰두하다"],["专著","zhuānzhù","전문 저서"],["比热容","bǐrèróng","비열"],["昼夜","zhòuyè","낮과 밤"]],"tr":["『삼국연의』는 제갈량·관우·조조 등 개성이 뚜렷한 인물들을 잇달아 그려 냈다.","바닷물은 비열이 커서 해안 도시의 밤낮 기온 차는 대개 내륙 도시보다 훨씬 작다.","학생들의 심미적 소양을 높이기 위해 학교는 이름난 화가 몇 분을 초청해 강연을 열고, 그들이 최근 몇 년간 그린 작품과 예술적 깨달음을 선보였다.","그는 은퇴한 뒤 지방 희곡사 연구에 몰두해, 무게 있는 학술 전문서 세 권을 잇달아 펴냈다."],"ow":[[["三国演义","Sānguó Yǎnyì","삼국연의"],["塑造","sùzào","(인물을) 형상화하다"],["诸葛亮","Zhūgě Liàng","제갈량"],["曹操","Cáo Cāo","조조"]],[["比热容","bǐrèróng","비열"],["沿海","yánhǎi","연해"],["昼夜","zhòuyè","낮과 밤"],["温差","wēnchā","온도 차"],["内陆","nèilù","내륙"]],[["审美","shěnměi","심미"],["素养","sùyǎng","소양"],["讲座","jiǎngzuò","강좌, 강연"],["心得","xīndé","깨달은 바"]],[["潜心","qiánxīn","몰두하다"],["戏曲","xìqǔ","희곡, 전통극"],["分量","fènliàng","무게, 비중"],["专著","zhuānzhù","전문 저서"]]]}],[{"o":["黄公望耗时数年创作的《富春山居图》，后来不幸被分割成两段，分藏于浙江和台北两地。","南极冰盖的平均厚度约两千米，储存了全球七成左右的淡水。","这位导演从不轻易接拍商业片，他更愿意把精力投入到自己真正感兴趣的题材上。","初学书法的人把历代经典碑帖应该反复揣摩，而不要急于追求所谓的个人风格。"],"a":3,"type":"부사·능원동사 위치","why":"능원동사 ‘应该’는 ‘把’ 구 앞에 와야 한다. “把…应该”는 어순이 틀렸다.","fix":"初学书法的人应该把历代经典碑帖反复揣摩，而不要急于追求所谓的个人风格。","words":[["黄公望","Huáng Gōngwàng","황공망(원대 화가)"],["分割","fēngē","나누다"],["冰盖","bīnggài","빙상"],["接拍","jiēpāi","(영화) 촬영을 맡다"],["碑帖","bēitiè","비첩(서예 교본 탁본)"],["揣摩","chuǎimó","곰곰이 따져 보다"]],"tr":["황공망이 몇 년에 걸쳐 그린 『부춘산거도』는 뒤에 불행히도 두 폭으로 나뉘어 저장과 타이베이 두 곳에 따로 소장되어 있다.","남극 빙상의 평균 두께는 약 2천 미터이며, 전 세계 민물의 70% 정도를 품고 있다.","이 감독은 상업 영화를 쉽게 맡지 않으며, 자신이 정말 관심 있는 소재에 힘을 쏟기를 더 좋아한다.","서예를 막 배우는 사람은 역대의 이름난 비첩을 거듭 깊이 살펴야 하며, 이른바 개인 풍격을 서둘러 좇아서는 안 된다."],"ow":[[["黄公望","Huáng Gōngwàng","황공망(원대 화가)"],["耗时","hàoshí","시간을 들이다"],["富春山居图","Fùchūn Shānjū Tú","부춘산거도"],["分割","fēngē","나누다"]],[["南极","nánjí","남극"],["冰盖","bīnggài","빙상"],["储存","chǔcún","저장하다"],["淡水","dànshuǐ","민물"]],[["轻易","qīngyì","쉽게"],["接拍","jiēpāi","(영화) 촬영을 맡다"],["精力","jīnglì","정력, 힘"],["题材","tícái","소재"]],[["碑帖","bēitiè","비첩(서예 교본 탁본)"],["揣摩","chuǎimó","곰곰이 따져 보다"],["急于","jíyú","서둘러 ~하려 하다"],["所谓","suǒwèi","이른바"]]]},{"o":["由于保存条件有限，这家地方档案馆把大量珍贵的民国戏单和唱片至今没有进行数字化处理。","海水之所以是咸的，是因为河流不断地把陆地岩石中的盐分带入海洋。","这艘远洋渔船配备了先进的声呐探鱼设备，能够准确判断鱼群的位置和规模。","在中国古典诗词中，“柳”常常被用来寄托离别时的依依不舍之情。"],"a":0,"type":"부정사 위치","why":"부정어 ‘没有’와 시간 부사 ‘至今’은 ‘把’ 구 앞에 와야 한다.","fix":"由于保存条件有限，这家地方档案馆至今没有把大量珍贵的民国戏单和唱片进行数字化处理。","words":[["档案馆","dàngànguǎn","기록 보관소"],["戏单","xìdān","공연 프로그램 전단"],["寄托","jìtuō","(감정을) 담다"],["依依不舍","yī yī bù shě","헤어지기 아쉬워하다"],["远洋","yuǎnyáng","원양"],["声呐","shēngnà","음파 탐지기"]],"tr":["보존 여건이 부족해 이 지방 기록 보관소는 많은 귀한 민국 시대 공연 전단과 음반을 아직 디지털화하지 못했다.","바닷물이 짠 것은 강물이 육지 암석 속 염분을 끊임없이 바다로 실어 나르기 때문이다.","이 원양 어선은 첨단 음파 어군 탐지 장비를 갖추고 있어 물고기 떼의 위치와 규모를 정확하게 알아낼 수 있다.","중국 고전 시가에서 '버들'은 이별할 때의 아쉬운 마음을 담는 데 자주 쓰인다."],"ow":[[["档案馆","dàng'ànguǎn","기록 보관소"],["民国","Mínguó","중화민국 시기"],["戏单","xìdān","공연 프로그램 전단"],["数字化","shùzìhuà","디지털화"]],[["岩石","yánshí","암석"],["盐分","yánfèn","염분"]],[["远洋","yuǎnyáng","원양"],["配备","pèibèi","갖추다"],["声呐","shēngnà","음파 탐지기"],["鱼群","yúqún","물고기 떼"]],[["诗词","shīcí","시와 사"],["寄托","jìtuō","(감정을) 담다"],["离别","líbié","이별"],["依依不舍","yīyī bù shě","헤어지기 아쉬워하다"]]]},{"o":["曾侯乙编钟出土于湖北随州，全套共六十五件，至今仍能演奏出完整的乐曲。","许多外国留学生非常对京剧中色彩鲜明、寓意丰富的脸谱艺术感兴趣，常常专程到剧院后台参观。","这片红树林是众多水鸟的栖息地，也起着防风消浪、净化海水的作用。","研究发现，长时间使用电子屏幕会减少眨眼次数，从而引起眼睛干涩和疲劳。"],"a":1,"type":"부사 위치","why":"정도부사 ‘非常’은 ‘对…’ 구 뒤, ‘感兴趣’ 바로 앞에 와야 한다.","fix":"许多外国留学生对京剧中色彩鲜明、寓意丰富的脸谱艺术非常感兴趣，常常专程到剧院后台参观。","words":[["编钟","biānzhōng","편종"],["曾侯乙","Zēng hóu Yǐ","증후을(전국 시대 제후)"],["寓意","yùyì","담긴 뜻"],["脸谱","liǎnpǔ","(경극) 얼굴 분장"],["红树林","hóngshùlín","맹그로브 숲"],["干涩","gānsè","메마르고 뻑뻑하다"]],"tr":["증후을 편종은 후베이 쑤이저우에서 출토되었으며, 한 벌이 모두 65점으로 지금도 완전한 곡을 연주할 수 있다.","많은 외국 유학생들이 색채가 뚜렷하고 뜻이 풍부한 경극 얼굴 분장 예술에 큰 흥미를 느껴, 자주 일부러 극장 무대 뒤를 찾아가 본다.","이 맹그로브 숲은 수많은 물새의 서식지이며, 바람과 파도를 막고 바닷물을 정화하는 역할도 한다.","연구에 따르면 전자 화면을 오래 보면 눈 깜빡임이 줄어 눈이 건조해지고 피로해진다."],"ow":[[["曾侯乙","Zēnghóu Yǐ","증후을(전국 시대 제후)"],["编钟","biānzhōng","편종"],["出土","chūtǔ","출토되다"],["随州","Suízhōu","쑤이저우"]],[["寓意","yùyì","담긴 뜻"],["脸谱","liǎnpǔ","(경극) 얼굴 분장"],["专程","zhuānchéng","일부러 찾아가다"],["后台","hòutái","무대 뒤"]],[["红树林","hóngshùlín","맹그로브 숲"],["栖息地","qīxīdì","서식지"],["净化","jìnghuà","정화하다"]],[["屏幕","píngmù","화면"],["眨眼","zhǎyǎn","눈을 깜빡이다"],["干涩","gānsè","메마르고 뻑뻑하다"],["疲劳","píláo","피로하다"]]]},{"o":["唐代颜真卿的《祭侄文稿》是在极度悲愤的情绪下写成的，被誉为“天下第二行书”。","这座水电站建成后，每年可为华东地区提供数百亿千瓦时的清洁电力。","这位旅居海外的作家写了一部长篇小说关于二十世纪三十年代上海弄堂生活，在华人读者中广受好评。","他们把收集到的上千首民歌整理成册，为研究西北地区的音乐传统留下了宝贵资料。"],"a":2,"type":"개사구 위치","why":"개사구 “关于…生活”가 꾸미는 명사 ‘长篇小说’ 뒤에 놓였다. ‘的’를 붙여 명사 앞으로 옮겨야 한다.","fix":"这位旅居海外的作家写了一部关于二十世纪三十年代上海弄堂生活的长篇小说，在华人读者中广受好评。","words":[["悲愤","bēifèn","비분"],["行书","xíngshū","행서"],["千瓦时","qiānwǎshí","킬로와트시"],["旅居","lǚjū","타향에 머물다"],["弄堂","lòngtáng","(상하이의) 골목"],["华人","huárén","화교·중국계 사람"]],"tr":["당나라 안진경의 『제질문고』는 극도로 비통하고 분한 마음으로 쓴 것으로, '천하제이행서'로 칭송된다.","이 수력 발전소가 완공되면 해마다 화둥 지역에 수백억 킬로와트시의 청정 전력을 공급할 수 있다.","해외에 사는 이 작가는 1930년대 상하이 골목 생활을 다룬 장편소설을 써서 중국계 독자들에게서 호평을 받았다.","그들은 모은 민요 천여 곡을 책으로 엮어 서북 지역의 음악 전통을 연구할 귀중한 자료를 남겼다."],"ow":[[["颜真卿","Yán Zhēnqīng","안진경"],["祭侄文稿","Jì Zhí Wéngǎo","제질문고(서예 작품)"],["悲愤","bēifèn","비분"],["行书","xíngshū","행서"]],[["水电站","shuǐdiànzhàn","수력 발전소"],["华东","Huádōng","화둥(중국 동부)"],["千瓦时","qiānwǎshí","킬로와트시"]],[["旅居","lǚjū","타향에 머물다"],["弄堂","lòngtáng","(상하이의) 골목"],["华人","huárén","중국계 사람"],["好评","hǎopíng","호평"]],[["民歌","míngē","민요"],["整理","zhěnglǐ","정리하다"],["宝贵","bǎoguì","귀중하다"]]]},{"o":["由于长期缺乏光照，生活在洞穴深处的一些鱼类，眼睛已经逐渐退化。","这部电影的配乐由一位年轻作曲家完成，他巧妙地将古筝的音色与交响乐融合在一起。","敦煌研究院的专家们花了数十年时间，为莫高窟建立起了一套完整的数字档案。","这位指挥家与柏林爱乐乐团合作了一场音乐会在去年的维也纳音乐节上，现场座无虚席。"],"a":3,"type":"개사구 위치","why":"장소를 나타내는 개사구 “在…音乐节上”은 동사 앞에 와야 하는데 목적어 뒤에 놓였다.","fix":"这位指挥家去年在维也纳音乐节上与柏林爱乐乐团合作了一场音乐会，现场座无虚席。","words":[["洞穴","dòngxué","동굴"],["退化","tuìhuà","퇴화하다"],["配乐","pèiyuè","영화 음악"],["古筝","gǔzhēng","고쟁"],["爱乐乐团","ài yuè yuè tuán","필하모닉 오케스트라"],["座无虚席","zuò wú xū xí","빈자리가 없다"]],"tr":["오랫동안 빛을 받지 못해 동굴 깊은 곳에 사는 몇몇 물고기는 눈이 점점 퇴화했다.","이 영화의 음악은 한 젊은 작곡가가 맡았는데, 그는 고쟁의 음색과 교향악을 솜씨 있게 하나로 녹여 냈다.","둔황연구원 전문가들은 수십 년에 걸쳐 막고굴의 완전한 디지털 기록을 구축했다.","이 지휘자는 지난해 빈 음악제에서 베를린 필하모닉과 함께 음악회를 열었는데, 객석이 빈자리 없이 꽉 찼다."],"ow":[[["光照","guāngzhào","빛을 쬠"],["洞穴","dòngxué","동굴"],["退化","tuìhuà","퇴화하다"]],[["配乐","pèiyuè","영화 음악"],["作曲家","zuòqǔjiā","작곡가"],["古筝","gǔzhēng","고쟁"],["音色","yīnsè","음색"],["交响乐","jiāoxiǎngyuè","교향악"]],[["敦煌","Dūnhuáng","둔황"],["研究院","yánjiūyuàn","연구원"],["莫高窟","Mògāo Kū","막고굴"],["档案","dàng'àn","기록, 파일"]],[["指挥家","zhǐhuījiā","지휘자"],["柏林","Bólín","베를린"],["爱乐乐团","àiyuè yuètuán","필하모닉 오케스트라"],["维也纳","Wéiyěnà","빈"],["座无虚席","zuò wú xū xí","빈자리가 없다"]]]},{"o":["这家博物馆为庆祝建馆六十周年，集中展出了精美的明清两代的一百多件官窑瓷器。","广东沿海一些古村落的蚝壳屋用成千上万只牡蛎壳砌成墙体，冬暖夏凉，坚固耐用。","新能源汽车的普及在减少尾气排放的同时，也对城市充电设施的建设提出了更高要求。","这首诗借秋天凋零的落叶，抒发了诗人对故乡和亲人的深切思念。"],"a":0,"type":"관형어 순서","why":"수량 ‘一百多件’은 ‘精美的’ 같은 형용사 꾸밈말보다 앞에 와야 한다.","fix":"这家博物馆为庆祝建馆六十周年，集中展出了一百多件明清两代的精美官窑瓷器。","words":[["官窑","guānyáo","관요(관청 가마)"],["尾气","wěiqì","배기가스"],["凋零","diāolíng","시들어 떨어지다"],["抒发","shūfā","(감정을) 나타내다"],["牡蛎","mǔlì","굴"],["砌","qì","(벽돌 등을) 쌓다"]],"tr":["이 박물관은 개관 60주년을 맞아 명·청 두 왕조의 정교하고 아름다운 관요 자기 백여 점을 한데 모아 전시했다.","광둥 연해의 몇몇 옛 마을에 있는 굴 껍데기 집은 수많은 굴 껍데기로 벽을 쌓아, 겨울엔 따뜻하고 여름엔 시원하며 튼튼하다.","신에너지 자동차가 널리 퍼지면서 배기가스는 줄었지만, 도시 충전 시설 건설에는 더 높은 요구가 생겼다.","이 시는 가을에 시들어 떨어지는 낙엽을 빌려, 고향과 가족에 대한 시인의 깊은 그리움을 나타냈다."],"ow":[[["庆祝","qìngzhù","경축하다"],["精美","jīngměi","정교하고 아름답다"],["官窑","guānyáo","관요(관청 가마)"],["瓷器","cíqì","자기"]],[["蚝壳屋","háokéwū","굴 껍데기 집"],["牡蛎","mǔlì","굴"],["砌","qì","(벽돌 등을) 쌓다"],["冬暖夏凉","dōng nuǎn xià liáng","겨울에 따뜻하고 여름에 시원하다"]],[["普及","pǔjí","보급되다"],["尾气","wěiqì","배기가스"],["排放","páifàng","배출하다"],["设施","shèshī","시설"]],[["凋零","diāolíng","시들어 떨어지다"],["抒发","shūfā","(감정을) 나타내다"],["深切","shēnqiè","깊고 절실하다"]]]},{"o":["皮影戏是用兽皮或纸板雕刻成人物剪影，借助灯光在幕布上表演故事的一种民间戏剧。","这次在上海展出的，是一批经过精心修复的、极其珍贵的、大英图书馆的敦煌写经残卷。","湖泊的富营养化会导致藻类大量繁殖，使水中的溶解氧急剧减少。","他将毕生积蓄捐给了家乡的小学，自己却一直过着简朴的生活。"],"a":1,"type":"관형어 순서","why":"소속을 나타내는 ‘大英图书馆的’는 여러 꾸밈말 가운데 맨 앞에 와야 한다.","fix":"这次在上海展出的，是大英图书馆的一批经过精心修复的、极其珍贵的敦煌写经残卷。","words":[["皮影戏","píyǐngxì","그림자극"],["剪影","jiǎnyǐng","실루엣"],["残卷","cánjuàn","남은 두루마리 조각"],["富营养化","fù yíng yǎng huà","부영양화"],["藻类","zǎolèi","조류"],["积蓄","jīxù","저축"]],"tr":["그림자극은 짐승 가죽이나 종이판을 오려 인물 실루엣을 만들고, 불빛을 이용해 막 위에서 이야기를 공연하는 민간 연극이다.","이번에 상하이에서 전시된 것은 영국 도서관이 소장한, 정성껏 복원된 매우 귀한 둔황 사경 잔권들이다.","호수가 부영양화되면 조류가 대량으로 번식해 물속의 용존 산소가 급격히 줄어든다.","그는 평생 모은 돈을 고향 초등학교에 기부하고 자신은 줄곧 검소하게 살았다."],"ow":[[["皮影戏","píyǐngxì","그림자극"],["兽皮","shòupí","짐승 가죽"],["雕刻","diāokè","새기다, 조각하다"],["剪影","jiǎnyǐng","실루엣"],["幕布","mùbù","막, 스크린"]],[["修复","xiūfù","복원하다"],["大英图书馆","Dàyīng Túshūguǎn","영국 도서관"],["敦煌","Dūnhuáng","둔황"],["残卷","cánjuàn","남은 두루마리 조각"]],[["富营养化","fùyíngyǎnghuà","부영양화"],["藻类","zǎolèi","조류"],["繁殖","fánzhí","번식하다"],["溶解氧","róngjiěyǎng","용존 산소"],["急剧","jíjù","급격하다"]],[["毕生","bìshēng","평생"],["积蓄","jīxù","저축"],["简朴","jiǎnpǔ","검소하다"]]]},{"o":["王羲之的《兰亭集序》真迹据传已随唐太宗陪葬昭陵，今天所见多为后人的摹本。","这座城市计划在五年内新建十余座社区图书馆，让居民步行十五分钟就能借到书。","这位老票友至今仍珍藏着泛黄的几张梅兰芳先生当年亲笔签名的演出剧照。","这家物流企业借助无人机配送，把山区包裹的送达时间缩短了一半以上。"],"a":2,"type":"관형어 순서","why":"‘泛黄的’ 같은 형용사 꾸밈말이 수량 ‘几张’과 소속 ‘梅兰芳先生…的’보다 앞에 놓여 순서가 틀렸다.","fix":"这位老票友至今仍珍藏着梅兰芳先生当年亲笔签名的几张泛黄的演出剧照。","words":[["真迹","zhēnjì","진본, 진필"],["陪葬","péizàng","순장하다(함께 묻다)"],["摹本","móběn","모사본"],["票友","piàoyǒu","아마추어 경극 애호가"],["泛黄","fànhuáng","누렇게 바래다"],["剧照","jùzhào","공연 사진"]],"tr":["왕희지의 『난정집서』 진본은 당 태종과 함께 소릉에 묻혔다고 전해지며, 오늘날 보는 것은 대부분 후대 사람의 모사본이다.","이 도시는 5년 안에 동네 도서관 10여 곳을 새로 지어, 주민들이 걸어서 15분이면 책을 빌릴 수 있게 할 계획이다.","이 늙은 경극 애호가는 메이란팡 선생이 당시 직접 서명한 누렇게 바랜 공연 사진 몇 장을 지금도 소중히 간직하고 있다.","이 물류 기업은 드론 배송으로 산간 지역 소포의 배달 시간을 절반 넘게 줄였다."],"ow":[[["王羲之","Wáng Xīzhī","왕희지"],["兰亭集序","Lántíng Jí Xù","난정집서"],["真迹","zhēnjì","진본"],["陪葬","péizàng","함께 묻다"],["昭陵","Zhāolíng","소릉(당 태종의 능)"],["摹本","móběn","모사본"]],[["社区","shèqū","지역 사회, 동네"],["步行","bùxíng","걷다"]],[["票友","piàoyǒu","아마추어 경극 애호가"],["珍藏","zhēncáng","소중히 간직하다"],["泛黄","fànhuáng","누렇게 바래다"],["梅兰芳","Méi Lánfāng","메이란팡"],["剧照","jùzhào","공연 사진"]],[["物流","wùliú","물류"],["无人机","wúrénjī","드론"],["配送","pèisòng","배송하다"],["包裹","bāoguǒ","소포"]]]},{"o":["京剧中的“生、旦、净、丑”四大行当，各有一套独特的表演程式。","为了防止水土流失，当地农民在山坡上修筑梯田、种植果树，取得了良好的生态效益。","这部纪录片用四年时间跟拍了一群藏羚羊的迁徙，记录下许多珍贵的画面。","这部小说的手稿在作者生前一直未能出版，直到他去世二十年后才被家人整理发现并交给出版社。"],"a":3,"type":"동작 순서","why":"먼저 ‘发现’해야 ‘整理’할 수 있으므로 “整理发现”은 순서가 거꾸로다.","fix":"这部小说的手稿在作者生前一直未能出版，直到他去世二十年后才被家人发现、整理并交给出版社。","words":[["行当","hángdang","(경극) 배역 유형"],["程式","chéngshì","정형화된 양식"],["梯田","tītián","계단식 논밭"],["藏羚羊","zànglíngyáng","티베트영양"],["手稿","shǒugǎo","원고"]],"tr":["경극의 '생·단·정·축' 네 가지 배역은 각각 독특한 연기 양식을 갖고 있다.","토양 유실을 막으려고 이 지역 농민들은 산비탈에 계단식 밭을 만들고 과일나무를 심어 좋은 생태적 효과를 거두었다.","이 다큐멘터리는 4년 동안 티베트영양 무리의 이동을 따라다니며 찍어 귀한 장면을 많이 담았다.","이 소설의 원고는 작가 생전에 끝내 출판되지 못했고, 그가 세상을 떠난 지 20년이 지나서야 가족이 찾아 정리해 출판사에 넘겼다."],"ow":[[["京剧","jīngjù","경극"],["行当","hángdang","(경극) 배역 유형"],["程式","chéngshì","정형화된 양식"]],[["水土流失","shuǐtǔ liúshī","토양 유실"],["修筑","xiūzhù","건설하다"],["梯田","tītián","계단식 논밭"],["效益","xiàoyì","효과, 이익"]],[["纪录片","jìlùpiàn","다큐멘터리"],["跟拍","gēnpāi","따라다니며 찍다"],["藏羚羊","zànglíngyáng","티베트영양"],["迁徙","qiānxǐ","이동하다"]],[["手稿","shǒugǎo","원고"],["生前","shēngqián","생전"],["出版社","chūbǎnshè","출판사"]]]},{"o":["在长达三十年的写作生涯中，这位作家先后创作并构思了十余部以黄土高原为背景的长篇小说。","云冈石窟开凿于北魏时期，其中的大佛高达十余米，气势雄伟。","运动后立即大量饮用冰水，可能会引起胃肠痉挛，因此应少量多次地补充温水。","随着电子支付的普及，越来越多的老年人也开始学习使用手机扫码付款。"],"a":0,"type":"동작 순서","why":"먼저 ‘构思’하고 나서 ‘创作’하므로 “创作并构思”는 순서가 거꾸로다.","fix":"在长达三十年的写作生涯中，这位作家先后构思并创作了十余部以黄土高原为背景的长篇小说。","words":[["生涯","shēngyá","생애, 경력"],["构思","gòusī","구상하다"],["云冈石窟","Yún gāng shí kū","윈강 석굴"],["开凿","kāizáo","파내다, 뚫다"],["痉挛","jìngluán","경련"]],"tr":["30년에 걸친 집필 생활 동안 이 작가는 황토고원을 배경으로 한 장편소설 10여 편을 잇달아 구상하고 써냈다.","윈강 석굴은 북위 시대에 파서 만들었으며, 그 안의 큰 불상은 높이가 10여 미터에 이르러 기세가 웅장하다.","운동 직후 찬물을 많이 마시면 위장 경련이 생길 수 있으므로, 따뜻한 물을 조금씩 여러 번 마셔야 한다.","전자 결제가 널리 퍼지면서 휴대 전화로 QR 코드를 찍어 돈을 내는 법을 배우는 노인도 갈수록 늘고 있다."],"ow":[[["生涯","shēngyá","생애, 경력"],["构思","gòusī","구상하다"],["黄土高原","Huángtǔ Gāoyuán","황토고원"]],[["云冈石窟","Yúngāng Shíkū","윈강 석굴"],["开凿","kāizáo","파내다"],["北魏","Běi Wèi","북위"],["雄伟","xióngwěi","웅장하다"]],[["立即","lìjí","즉시"],["痉挛","jìngluán","경련"],["补充","bǔchōng","보충하다"]],[["支付","zhīfù","지불하다"],["普及","pǔjí","보급되다"],["扫码","sǎomǎ","QR 코드를 찍다"]]]}],[{"o":["这位画家常年住在渔村，用水墨描绘渔港的晨雾与归帆，作品中充满了浓郁的海洋气息。","只有深入体验角色的内心世界，演员就能把人物塑造得真实可信、有血有肉。","尽管人工智能的发展日新月异，但它在理解人类情感方面仍面临许多挑战。","这种候鸟每年秋天从西伯利亚飞往长江中下游越冬，行程长达数千公里。"],"a":1,"type":"짝 오류","why":"‘只有’는 ‘才’와 짝을 이룬다. “只有…就”는 짝이 맞지 않는다.","fix":"只有深入体验角色的内心世界，演员才能把人物塑造得真实可信、有血有肉。","words":[["有血有肉","yǒu xuè yǒu ròu","생생하게 살아 있다"],["日新月异","rì xīn yuè yì","나날이 새로워지다"],["西伯利亚","Xī bó lì yà","시베리아"],["归帆","guīfān","돌아오는 배"],["浓郁","nóngyù","짙다"]],"tr":["이 화가는 오랫동안 어촌에 살며 먹으로 어항의 새벽안개와 돌아오는 배를 그려, 작품마다 짙은 바다 내음이 가득하다.","배역의 속마음을 깊이 겪어 보아야만 배우는 인물을 진실하고 생생하게 그려 낼 수 있다.","인공 지능은 나날이 발전하고 있지만, 사람의 감정을 이해하는 데는 아직 많은 어려움을 안고 있다.","이 철새는 해마다 가을이면 시베리아에서 창장 중하류로 날아와 겨울을 나는데, 그 거리가 수천 킬로미터에 이른다."],"ow":[[["渔村","yúcūn","어촌"],["水墨","shuǐmò","수묵"],["渔港","yúgǎng","어항"],["归帆","guīfān","돌아오는 배"],["浓郁","nóngyù","짙다"]],[["体验","tǐyàn","체험하다"],["塑造","sùzào","(인물을) 형상화하다"],["有血有肉","yǒu xuè yǒu ròu","생생하게 살아 있다"]],[["人工智能","réngōng zhìnéng","인공 지능"],["日新月异","rì xīn yuè yì","나날이 새로워지다"],["挑战","tiǎozhàn","도전, 어려움"]],[["候鸟","hòuniǎo","철새"],["西伯利亚","Xībólìyà","시베리아"],["越冬","yuèdōng","겨울을 나다"],["行程","xíngchéng","여정, 거리"]]]},{"o":["古琴是中国最古老的弹拨乐器之一，2003年被列入“人类口头和非物质遗产代表作”。","这个小镇虽然面积不大，却保存着二十多座明清时期的古民居。","即使这部电影的特效制作达到了国际一流水平，但如果故事空洞乏味，很难真正打动观众。","研究人员通过分析沉积在海底的贝壳化石，还原了这片海域数千年来水温的变化。"],"a":2,"type":"짝 오류","why":"‘即使’는 ‘也’와 짝을 이룬다. ‘但’을 쓰고 ‘也’를 빠뜨려 짝이 맞지 않는다.","fix":"即使这部电影的特效制作达到了国际一流水平，如果故事空洞乏味，也很难真正打动观众。","words":[["弹拨乐器","tán bō yuè qì","현을 뜯는 악기"],["民居","mínjū","민가"],["特效","tèxiào","특수 효과"],["空洞","kōngdòng","내용이 없다"],["乏味","fáwèi","무미건조하다"],["沉积","chénjī","퇴적하다"],["还原","huányuán","복원하다"]],"tr":["고금은 중국에서 가장 오래된 현을 뜯는 악기 가운데 하나로, 2003년 '인류 구전 및 무형 유산 걸작'에 올랐다.","이 작은 마을은 면적은 크지 않지만 명·청 시대의 옛 민가를 스무 채 넘게 간직하고 있다.","이 영화의 특수 효과가 세계 최고 수준에 이르렀다 해도, 이야기가 공허하고 지루하면 관객을 진정으로 감동시키기는 어렵다.","연구진은 해저에 쌓인 조개 화석을 분석해, 이 바다의 수온이 수천 년 동안 어떻게 바뀌어 왔는지 되살려 냈다."],"ow":[[["古琴","gǔqín","고금(칠현금)"],["弹拨乐器","tánbō yuèqì","현을 뜯는 악기"],["遗产","yíchǎn","유산"]],[["小镇","xiǎozhèn","작은 마을"],["民居","mínjū","민가"]],[["特效","tèxiào","특수 효과"],["空洞","kōngdòng","내용이 없다"],["乏味","fáwèi","무미건조하다"],["打动","dǎdòng","감동시키다"]],[["沉积","chénjī","퇴적하다"],["贝壳","bèiké","조개껍데기"],["化石","huàshí","화석"],["还原","huányuán","복원하다"],["海域","hǎiyù","해역"]]]},{"o":["鲁迅的《狂人日记》发表于1918年，是中国现代文学史上第一篇白话小说。","与其把时间浪费在无谓的争论上，不如静下心来把手头的研究做扎实。","这座桥采用了独特的抗震设计，即使遭遇八级地震，主体结构也不会受到严重损坏。","既然你已经决定报考戏曲学院，才应该从现在起每天坚持练功，不能有丝毫懈怠。"],"a":3,"type":"짝 오류","why":"‘既然’은 ‘就’와 짝을 이룬다. “既然…才”는 짝이 맞지 않는다.","fix":"既然你已经决定报考戏曲学院，就应该从现在起每天坚持练功，不能有丝毫懈怠。","words":[["白话","báihuà","백화(구어체 글)"],["无谓","wúwèi","쓸데없다"],["抗震","kàngzhèn","내진"],["练功","liàngōng","기량을 닦다"],["丝毫","sīháo","조금도"],["懈怠","xièdài","게으름"]],"tr":["루쉰의 『광인일기』는 1918년에 발표된 중국 현대 문학사 최초의 백화 소설이다.","쓸데없는 논쟁에 시간을 허비하느니 차분히 마음을 가라앉히고 하던 연구를 탄탄하게 해 두는 편이 낫다.","이 다리는 독특한 내진 설계를 적용해, 규모 8의 지진이 나더라도 주요 구조물이 심하게 손상되지 않는다.","이미 희곡 학교에 지원하기로 마음먹었다면 지금부터 날마다 꾸준히 기량을 닦아야 하고, 조금도 게을러서는 안 된다."],"ow":[[["鲁迅","Lǔ Xùn","루쉰"],["狂人日记","Kuángrén Rìjì","광인일기"],["白话","báihuà","백화(구어체 글)"]],[["与其","yǔqí","~하느니"],["无谓","wúwèi","쓸데없다"],["争论","zhēnglùn","논쟁"],["扎实","zhāshi","탄탄하다"]],[["抗震","kàngzhèn","내진"],["遭遇","zāoyù","맞닥뜨리다"],["结构","jiégòu","구조"],["损坏","sǔnhuài","손상되다"]],[["戏曲","xìqǔ","희곡, 전통극"],["练功","liàngōng","기량을 닦다"],["丝毫","sīháo","조금도"],["懈怠","xièdài","게으름"]]]},{"o":["不但梅兰芳精通京剧表演，而且在昆曲和绘画方面也颇有建树。","农作物秸秆如果随意焚烧，不仅会浪费资源，还会严重污染空气。","那年夏天，这支考古队在黄河岸边的一处遗址中发现了大量新石器时代的彩陶。","适度的音乐训练有助于提高儿童的专注力和语言能力，这一点已被多项研究证实。"],"a":0,"type":"관련사 위치","why":"앞뒤 절의 주어가 같으면 ‘不但’은 주어 ‘梅兰芳’ 뒤에 와야 한다.","fix":"梅兰芳不但精通京剧表演，而且在昆曲和绘画方面也颇有建树。","words":[["精通","jīngtōng","정통하다"],["建树","jiànshù","업적, 성과"],["秸秆","jiēgǎn","(농작물) 줄기, 짚"],["焚烧","fénshāo","태우다"],["遗址","yízhǐ","유적지"],["彩陶","cǎitáo","채도(채색 토기)"]],"tr":["메이란팡은 경극 연기에 정통했을 뿐 아니라 곤곡과 그림에서도 꽤 큰 성과를 냈다.","농작물 짚을 함부로 태우면 자원을 낭비할 뿐 아니라 공기도 심하게 오염시킨다.","그해 여름 이 발굴단은 황허 기슭의 한 유적지에서 신석기 시대 채색 토기를 대량으로 발견했다.","적당한 음악 훈련은 아이의 집중력과 언어 능력을 높이는 데 도움이 되며, 이는 여러 연구로 확인되었다."],"ow":[[["梅兰芳","Méi Lánfāng","메이란팡"],["精通","jīngtōng","정통하다"],["昆曲","kūnqǔ","곤곡"],["建树","jiànshù","업적, 성과"]],[["农作物","nóngzuòwù","농작물"],["秸秆","jiēgǎn","짚, 줄기"],["焚烧","fénshāo","태우다"]],[["考古队","kǎogǔduì","발굴단"],["遗址","yízhǐ","유적지"],["新石器时代","xīnshíqì shídài","신석기 시대"],["彩陶","cǎitáo","채도(채색 토기)"]],[["适度","shìdù","적당하다"],["专注力","zhuānzhùlì","집중력"],["证实","zhèngshí","증명하다"]]]},{"o":["宋词按风格大致可分为婉约和豪放两派，前者以柳永、李清照为代表，后者以苏轼、辛弃疾为代表。","既这部纪录片展现了青藏高原壮美的自然风光，又真实记录了当地牧民的日常生活。","在人类历史上，许多重大发现都源于科学家对日常现象的敏锐观察。","这家企业的产品出口到四十多个国家和地区，年销售额连续五年保持两位数增长。"],"a":1,"type":"관련사 위치","why":"‘既…又…’는 같은 주어 뒤에 와야 한다. ‘既’가 주어 ‘这部纪录片’ 앞에 놓였다.","fix":"这部纪录片既展现了青藏高原壮美的自然风光，又真实记录了当地牧民的日常生活。","words":[["婉约","wǎnyuē","완약(부드럽고 섬세한 풍)"],["豪放","háofàng","호방하다"],["辛弃疾","Xīn Qìjí","신기질(남송 사인)"],["壮美","zhuàngměi","웅장하고 아름답다"],["牧民","mùmín","유목민"],["源于","yuányú","~에서 비롯되다"]],"tr":["송사는 풍격에 따라 크게 완약파와 호방파로 나눌 수 있는데, 앞쪽은 유영과 이청조, 뒤쪽은 소식과 신기질이 대표한다.","이 다큐멘터리는 칭짱고원의 웅장하고 아름다운 자연 풍경을 보여 주는 동시에, 그곳 유목민의 일상도 생생하게 담았다.","인류 역사에서 많은 중대한 발견은 일상 현상에 대한 과학자의 예리한 관찰에서 비롯되었다.","이 기업의 제품은 40여 개 나라와 지역으로 수출되며, 연 매출은 5년 연속 두 자릿수 성장을 이어 갔다."],"ow":[[["宋词","sòngcí","송사(송대의 사)"],["婉约","wǎnyuē","부드럽고 섬세하다"],["豪放","háofàng","호방하다"],["李清照","Lǐ Qīngzhào","이청조"],["辛弃疾","Xīn Qìjí","신기질"]],[["纪录片","jìlùpiàn","다큐멘터리"],["青藏高原","Qīngzàng Gāoyuán","칭짱고원"],["壮美","zhuàngměi","웅장하고 아름답다"],["牧民","mùmín","유목민"]],[["源于","yuányú","~에서 비롯되다"],["敏锐","mǐnruì","예리하다"]],[["出口","chūkǒu","수출하다"],["销售额","xiāoshòu'é","매출액"]]]},{"o":["齐白石笔下的虾栩栩如生，寥寥数笔便能表现出虾在水中游动的神态。","我们不但要学习前人的经验，更要在实践中不断探索新的方法。","这部歌剧的演员阵容十分强大，舞台设计也美轮美奂，因此首演当晚上座率还不到三成。","部分发达国家的人口出生率持续走低，劳动力短缺问题日益凸显。"],"a":2,"type":"논리 관계","why":"배우와 무대가 훌륭한데 관객이 적었으므로 앞뒤는 역접이다. ‘因此’가 아니라 ‘但’을 써야 한다.","fix":"这部歌剧的演员阵容十分强大，舞台设计也美轮美奂，但首演当晚上座率还不到三成。","words":[["栩栩如生","xǔ xǔ rú shēng","살아 있는 듯 생생하다"],["寥寥","liáoliáo","매우 적다"],["阵容","zhènróng","진용, 라인업"],["美轮美奂","měi lún měi huàn","웅장하고 화려하다"],["上座率","shàngzuòlǜ","객석 점유율"],["凸显","tūxiǎn","두드러지다"]],"tr":["치바이스가 그린 새우는 살아 있는 듯 생생해서, 붓질 몇 번만으로 새우가 물속을 헤엄치는 모습을 나타낸다.","우리는 앞사람의 경험을 배울 뿐 아니라, 실천 속에서 새로운 방법을 끊임없이 찾아야 한다.","이 오페라는 출연진이 매우 화려하고 무대 디자인도 웅장하고 아름다웠지만, 초연 당일 밤 객석 점유율은 30%도 되지 않았다.","일부 선진국의 출생률이 계속 낮아지면서 노동력 부족 문제가 날로 두드러지고 있다."],"ow":[[["齐白石","Qí Báishí","치바이스(화가)"],["栩栩如生","xǔxǔ rú shēng","살아 있는 듯 생생하다"],["寥寥","liáoliáo","매우 적다"],["神态","shéntài","모습, 표정"]],[["实践","shíjiàn","실천"],["探索","tànsuǒ","탐색하다"]],[["歌剧","gējù","오페라"],["阵容","zhènróng","라인업"],["美轮美奂","měi lún měi huàn","웅장하고 화려하다"],["首演","shǒuyǎn","초연"],["上座率","shàngzuòlǜ","객석 점유율"]],[["出生率","chūshēnglǜ","출생률"],["短缺","duǎnquē","부족하다"],["凸显","tūxiǎn","두드러지다"]]]},{"o":["京剧的伴奏乐器分为文场和武场，前者以京胡为主，后者以鼓板为主。","这项技术虽然成本较高，但能大幅提高能源利用效率，长远来看是划算的。","地球上的淡水资源本就有限，加上工业污染日趋严重，许多地区的饮水安全面临威胁。","这位中国作家的小说不但在海外多个国家出版发行，甚至在国内也登上了畅销书排行榜。"],"a":3,"type":"논리 관계","why":"중국 작가가 국내에서 팔리는 것은 당연하고 해외 출판이 더 놀라운 일이다. ‘不但…甚至’는 가벼운 것에서 무거운 것으로 가야 하는데 거꾸로 되었다.","fix":"这位中国作家的小说不但在国内登上了畅销书排行榜，甚至在海外多个国家出版发行。","words":[["伴奏","bànzòu","반주"],["京胡","jīnghú","경호(경극용 현악기)"],["鼓板","gǔbǎn","북과 박판"],["划算","huásuàn","수지가 맞다"],["日趋","rìqū","날로"],["畅销书","chàngxiāoshū","베스트셀러"]],"tr":["경극의 반주 악기는 문장과 무장으로 나뉘는데, 문장은 경호가, 무장은 북과 박판이 중심이다.","이 기술은 비용이 비교적 높지만 에너지 효율을 크게 높일 수 있어, 길게 보면 수지가 맞는다.","지구의 민물 자원은 본래 한정되어 있는데, 산업 오염까지 날로 심해져 많은 지역의 식수 안전이 위협받고 있다.","이 중국 작가의 소설은 국내 베스트셀러 순위에 올랐을 뿐 아니라, 해외 여러 나라에서도 출판되었다."],"ow":[[["伴奏","bànzòu","반주"],["文场","wénchǎng","문장(현악·관악 반주)"],["武场","wǔchǎng","무장(타악 반주)"],["京胡","jīnghú","경호"],["鼓板","gǔbǎn","북과 박판"]],[["成本","chéngběn","원가, 비용"],["效率","xiàolǜ","효율"],["划算","huásuàn","수지가 맞다"]],[["淡水","dànshuǐ","민물"],["日趋","rìqū","날로"],["威胁","wēixié","위협"]],[["发行","fāxíng","발행하다"],["畅销书","chàngxiāoshū","베스트셀러"],["排行榜","páihángbǎng","순위표"]]]},{"o":["这位作家一生创作的作品数量并不多，而且几乎每一部都称得上精品，在文坛享有很高声誉。","古人常用“结草衔环”来比喻感恩图报，这个成语分别源自两个不同的典故。","这位植物学家走遍了横断山区的各个角落，采集了数万份植物标本。","由于电池技术的进步，新一代电动汽车的续航里程已经超过了六百公里。"],"a":0,"type":"논리 관계","why":"작품이 많지 않은데 하나하나가 명작이라는 것은 역접이다. 점층의 ‘而且’가 아니라 ‘但’을 써야 한다.","fix":"这位作家一生创作的作品数量并不多，但几乎每一部都称得上精品，在文坛享有很高声誉。","words":[["精品","jīngpǐn","걸작"],["文坛","wéntán","문단"],["结草衔环","jié cǎo xián huán","죽어서도 은혜를 갚다"],["典故","diǎngù","전고, 고사"],["横断山","Héng duàn shān","헝돤산맥"],["续航","xùháng","연속 주행"]],"tr":["이 작가가 평생 쓴 작품은 많지 않지만 거의 한 편 한 편이 걸작이라 할 만해, 문단에서 높은 명성을 누린다.","옛사람들은 은혜를 잊지 않고 갚는 것을 '결초함환'에 빗대곤 했는데, 이 성어는 서로 다른 두 고사에서 각각 나왔다.","이 식물학자는 헝돤산맥 구석구석을 누비며 식물 표본 수만 점을 채집했다.","배터리 기술이 발전하면서 새 세대 전기차의 주행 거리는 이미 600킬로미터를 넘어섰다."],"ow":[[["精品","jīngpǐn","걸작"],["文坛","wéntán","문단"],["声誉","shēngyù","명성"]],[["结草衔环","jié cǎo xián huán","죽어서도 은혜를 갚다"],["比喻","bǐyù","비유하다"],["感恩图报","gǎn ēn tú bào","은혜를 느끼고 갚으려 하다"],["典故","diǎngù","전고, 고사"]],[["横断山","Héngduàn Shān","헝돤산맥"],["角落","jiǎoluò","구석"],["采集","cǎijí","채집하다"],["标本","biāoběn","표본"]],[["续航","xùháng","연속 주행"],["里程","lǐchéng","거리"]]]},{"o":["这首曲子以江南丝竹为基调，融入了现代管弦乐的配器手法。","对于这次电影节评选结果的公正性上，不少业内人士都提出了质疑。","远洋货轮排放的压舱水中常常夹带外来生物，它们一旦在异地海域繁衍，就可能破坏当地生态。","他把多年来走访各地搜集到的民间谚语汇编成书，为语言学研究提供了丰富的素材。"],"a":1,"type":"개사 오용","why":"‘对于…’와 ‘在…上’ 두 구조가 섞였다. ‘对于’를 쓰면 끝의 ‘上’을 빼야 한다.","fix":"对于这次电影节评选结果的公正性，不少业内人士都提出了质疑。","words":[["丝竹","sīzhú","사죽(현악기와 관악기 합주)"],["配器","pèiqì","편곡(악기 배치)"],["质疑","zhìyí","의문을 제기하다"],["繁衍","fányǎn","번식하다"],["谚语","yànyǔ","속담"],["汇编","huìbiān","엮다, 편찬하다"],["压舱水","yācāngshuǐ","선박 평형수"],["夹带","jiādài","섞여 들다"]],"tr":["이 곡은 강남 사죽을 바탕으로 현대 관현악의 편곡 기법을 녹여 냈다.","이번 영화제 심사 결과의 공정성에 대해 많은 업계 인사들이 의문을 제기했다.","원양 화물선이 내보내는 선박 평형수에는 외래 생물이 자주 섞여 들어 있어, 이들이 다른 바다에서 번식하면 그곳 생태를 해칠 수 있다.","그는 여러 해 동안 각지를 찾아다니며 모은 민간 속담을 책으로 엮어, 언어학 연구에 풍부한 자료를 제공했다."],"ow":[[["丝竹","sīzhú","사죽(현악기와 관악기 합주)"],["基调","jīdiào","기조"],["管弦乐","guǎnxiányuè","관현악"],["配器","pèiqì","편곡(악기 배치)"]],[["评选","píngxuǎn","심사하여 뽑다"],["公正性","gōngzhèngxìng","공정성"],["质疑","zhìyí","의문을 제기하다"]],[["货轮","huòlún","화물선"],["压舱水","yācāngshuǐ","선박 평형수"],["夹带","jiādài","섞여 들다"],["繁衍","fányǎn","번식하다"]],[["谚语","yànyǔ","속담"],["汇编","huìbiān","엮다"],["素材","sùcái","소재, 자료"]]]},{"o":["二胡虽然只有两根弦，却能演奏出丰富细腻、变化多端的音色。","在全球变暖的背景下，北极海冰的面积正以惊人的速度缩小。","在这位老艺术家的言传身教，一批年轻的木偶戏演员迅速成长起来，成为剧团的骨干力量。","这家医院率先引进了手术机器人，使许多复杂手术的创伤大大减小。"],"a":2,"type":"개사 오용","why":"“在…言传身教” 뒤에 ‘下’가 빠졌다. ‘在…下’가 되어야 조건을 나타낸다.","fix":"在这位老艺术家的言传身教下，一批年轻的木偶戏演员迅速成长起来，成为剧团的骨干力量。","words":[["变化多端","biàn huà duō duān","변화무쌍하다"],["言传身教","yán chuán shēn jiào","말과 행동으로 가르치다"],["木偶戏","mùǒuxì","인형극"],["骨干","gǔgàn","중추"],["率先","shuàixiān","앞장서서"],["创伤","chuāngshāng","상처"]],"tr":["얼후는 줄이 두 개뿐이지만 풍부하고 섬세하며 변화무쌍한 음색을 낼 수 있다.","지구 온난화 속에서 북극 바다 얼음의 면적이 놀라운 속도로 줄어들고 있다.","이 노예술가가 말과 행동으로 가르친 덕분에 젊은 인형극 배우들이 빠르게 성장해 극단의 중추가 되었다.","이 병원은 수술 로봇을 앞장서 들여와 여러 복잡한 수술의 상처를 크게 줄였다."],"ow":[[["二胡","èrhú","얼후"],["细腻","xìnì","섬세하다"],["变化多端","biànhuà duōduān","변화무쌍하다"]],[["全球变暖","quánqiú biànnuǎn","지구 온난화"],["北极","běijí","북극"],["海冰","hǎibīng","바다 얼음"]],[["言传身教","yán chuán shēn jiào","말과 행동으로 가르치다"],["木偶戏","mù'ǒuxì","인형극"],["剧团","jùtuán","극단"],["骨干","gǔgàn","중추"]],[["率先","shuàixiān","앞장서서"],["引进","yǐnjìn","도입하다"],["创伤","chuāngshāng","상처"]]]}],[{"o":["越剧发源于浙江嵊州，以抒情见长，表演细腻婉约，在江南一带拥有众多戏迷。","这种疫苗并非没有副作用，只是其发生概率极低，且大多症状轻微。","为了避免这批刚出土的竹简不因脱水而开裂变形，考古人员立即将其浸泡在特制的溶液中。","他虽然从没受过专业训练，但凭着对音乐的热爱，自学掌握了多种民族乐器的演奏技巧。"],"a":2,"type":"다중 부정","why":"‘避免’에 이미 ‘하지 않게 하다’는 뜻이 있어 뒤에 ‘不’를 더하면 ‘갈라지게 한다’는 정반대 뜻이 된다.","fix":"为了避免这批刚出土的竹简因脱水而开裂变形，考古人员立即将其浸泡在特制的溶液中。","words":[["嵊州","Shèng zhōu","성저우(저장성의 도시)"],["见长","jiàncháng","~에 뛰어나다"],["戏迷","xìmí","연극 애호가"],["疫苗","yìmiáo","백신"],["竹简","zhújiǎn","죽간"],["浸泡","jìnpào","담그다"]],"tr":["월극은 저장 성저우에서 생겨났으며 서정에 뛰어나고 연기가 섬세하고 부드러워 강남 일대에 팬이 많다.","이 백신에 부작용이 없는 것은 아니지만, 생길 확률이 매우 낮고 대부분 증상도 가볍다.","막 출토된 이 죽간들이 수분을 잃어 갈라지거나 뒤틀리지 않도록 발굴단은 곧바로 특수 용액에 담갔다.","그는 전문 교육을 받은 적이 없지만 음악에 대한 사랑 하나로 여러 민족 악기의 연주 기법을 혼자 익혔다."],"ow":[[["越剧","yuèjù","월극"],["嵊州","Shèngzhōu","성저우"],["抒情","shūqíng","서정"],["见长","jiàncháng","~에 뛰어나다"],["戏迷","xìmí","연극 애호가"]],[["疫苗","yìmiáo","백신"],["并非","bìngfēi","결코 ~이 아니다"],["副作用","fùzuòyòng","부작용"],["概率","gàilǜ","확률"]],[["竹简","zhújiǎn","죽간"],["脱水","tuōshuǐ","수분을 잃다"],["变形","biànxíng","변형되다"],["浸泡","jìnpào","담그다"],["溶液","róngyè","용액"]],[["凭着","píngzhe","~에 기대어"],["技巧","jìqiǎo","기교"]]]},{"o":["由于全球气候持续变暖，喜马拉雅山区的许多冰川正在加速消融，冰湖溃决的风险也随之上升。","海明威的小说《老人与海》讲述了古巴老渔夫与一条大马林鱼在海上搏斗的故事，语言简洁而有力。","互联网的普及深刻改变了人们获取信息和相互交流的方式。","初次登台的演员难免不会因为紧张而忘词，这时同台的老演员往往会巧妙地帮忙圆场。"],"a":3,"type":"다중 부정","why":"‘难免(피하기 어렵다)’ 뒤에 ‘不会’를 붙이면 ‘대사를 잊지 않을 수밖에 없다’가 되어 뜻이 뒤집힌다.","fix":"初次登台的演员难免会因为紧张而忘词，这时同台的老演员往往会巧妙地帮忙圆场。","words":[["消融","xiāoróng","녹다"],["难免","nánmiǎn","피하기 어렵다"],["圆场","yuánchǎng","(어색한 상황을) 수습하다"],["海明威","Hǎi míng wēi","헤밍웨이"],["马林鱼","mǎlínyú","청새치"],["搏斗","bódòu","격투하다"]],"tr":["지구 기후가 계속 따뜻해지면서 히말라야 산지의 많은 빙하가 빠르게 녹고 있어, 빙하호가 터질 위험도 함께 커지고 있다.","헤밍웨이의 소설 『노인과 바다』는 쿠바의 늙은 어부가 큰 청새치와 바다에서 사투를 벌이는 이야기로, 문장이 간결하고 힘 있다.","인터넷이 널리 퍼지면서 사람들이 정보를 얻고 서로 소통하는 방식이 크게 달라졌다.","처음 무대에 서는 배우는 긴장해서 대사를 잊기 쉬운데, 이럴 때 함께 선 선배 배우가 흔히 재치 있게 수습을 돕는다."],"ow":[[["喜马拉雅","Xǐmǎlāyǎ","히말라야"],["冰川","bīngchuān","빙하"],["消融","xiāoróng","녹다"],["溃决","kuìjué","(둑이) 터지다"]],[["海明威","Hǎimíngwēi","헤밍웨이"],["古巴","Gǔbā","쿠바"],["马林鱼","mǎlínyú","청새치"],["搏斗","bódòu","격투하다"],["简洁","jiǎnjié","간결하다"]],[["互联网","hùliánwǎng","인터넷"],["普及","pǔjí","보급되다"],["获取","huòqǔ","얻다"]],[["登台","dēngtái","무대에 오르다"],["难免","nánmiǎn","피하기 어렵다"],["巧妙","qiǎomiào","교묘하다"],["圆场","yuánchǎng","(어색한 상황을) 수습하다"]]]},{"o":["剧院的工作人员一再提醒，演出过程中严禁观众不得使用闪光灯拍照，以免干扰演员表演。","徽派建筑以白墙黛瓦、马头墙为主要特征，在皖南古村落中至今随处可见。","他的建议看似无足轻重，事后证明却对整个项目的成败起到了关键作用。","无论科技如何发展，书籍在传承人类文明方面的作用都是不可替代的。"],"a":0,"type":"다중 부정","why":"‘严禁(엄금하다)’과 ‘不得(해서는 안 된다)’가 겹쳐 ‘사용하지 않는 것을 금지한다’는 뜻이 된다.","fix":"剧院的工作人员一再提醒，演出过程中严禁观众使用闪光灯拍照，以免干扰演员表演。","words":[["严禁","yánjìn","엄금하다"],["干扰","gānrǎo","방해하다"],["徽派","huīpài","후이저우 양식"],["黛瓦","dàiwǎ","검푸른 기와"],["皖南","Wǎn nán","안후이 남부"],["无足轻重","wú zú qīng zhòng","대수롭지 않다"]],"tr":["극장 직원들은 공연 중에 관객이 플래시를 터뜨려 사진을 찍는 것을 엄격히 금한다고 거듭 알리며, 배우의 연기를 방해하지 않도록 당부했다.","휘파 건축은 흰 벽과 검푸른 기와, 말머리 담을 주요 특징으로 하며, 안후이 남부의 옛 마을에서는 지금도 어디서나 볼 수 있다.","그의 제안은 대수롭지 않아 보였지만, 나중에 보니 사업 전체의 성패에 결정적인 역할을 했다.","과학 기술이 어떻게 발전하든 인류 문명을 이어 가는 데서 책의 역할은 무엇으로도 대신할 수 없다."],"ow":[[["严禁","yánjìn","엄금하다"],["闪光灯","shǎnguāngdēng","플래시"],["以免","yǐmiǎn","~하지 않도록"],["干扰","gānrǎo","방해하다"]],[["徽派","huīpài","후이저우 양식"],["黛瓦","dàiwǎ","검푸른 기와"],["马头墙","mǎtóuqiáng","말머리 모양 담"],["皖南","Wǎnnán","안후이 남부"]],[["无足轻重","wú zú qīng zhòng","대수롭지 않다"],["成败","chéngbài","성패"]],[["传承","chuánchéng","전승하다"],["文明","wénmíng","문명"],["替代","tìdài","대체하다"]]]},{"o":["李清照的词前期多写闺中生活，南渡之后则多抒发国破家亡的哀愁。","换装新型节能发动机后，这艘渔船每次出海的燃油消耗比过去减少了将近两倍，船主的成本负担大大减轻。","这家企业去年的研发投入比前年增加了一倍，新产品数量也随之大幅增长。","现代社会生活节奏加快，越来越多的人开始通过冥想来缓解焦虑情绪。"],"a":1,"type":"배수 감소","why":"줄어드는 것은 ‘배(倍)’로 말할 수 없다. “减少了将近两倍”가 아니라 ‘减少了将近三分之二’처럼 분수로 써야 한다.","fix":"换装新型节能发动机后，这艘渔船每次出海的燃油消耗比过去减少了将近三分之二，船主的成本负担大大减轻。","words":[["闺中","guīzhōng","규방 안"],["南渡","nándù","(송 왕조의) 남쪽 이주"],["冥想","míngxiǎng","명상"],["焦虑","jiāolǜ","불안"],["燃油","rányóu","연료유"],["负担","fùdān","부담"]],"tr":["이청조의 사는 앞 시기에는 주로 규방 생활을 그렸고, 남쪽으로 옮겨 간 뒤에는 나라가 망하고 집안이 무너진 슬픔을 주로 노래했다.","새 에너지 절약형 엔진으로 바꾼 뒤 이 어선이 한 번 출어할 때 쓰는 연료는 예전보다 크게 줄어 선주의 비용 부담이 많이 가벼워졌다.","이 기업의 지난해 연구 개발 투자는 그 전해보다 두 배로 늘었고, 신제품 수도 그에 따라 크게 늘었다.","현대 사회의 생활 속도가 빨라지면서 명상으로 불안을 달래는 사람이 갈수록 늘고 있다."],"ow":[[["李清照","Lǐ Qīngzhào","이청조"],["闺中","guīzhōng","규방 안"],["南渡","nándù","(송 왕조의) 남쪽 이주"],["国破家亡","guó pò jiā wáng","나라가 망하고 집안이 무너지다"],["哀愁","āichóu","슬픔"]],[["节能","jiénéng","에너지 절약"],["发动机","fādòngjī","엔진"],["燃油","rányóu","연료유"],["负担","fùdān","부담"]],[["研发","yánfā","연구 개발"],["投入","tóurù","투입"]],[["节奏","jiézòu","리듬, 속도"],["冥想","míngxiǎng","명상"],["缓解","huǎnjiě","완화하다"],["焦虑","jiāolǜ","불안"]]]},{"o":["这部以闽南渔村为背景的电影，用大量长镜头展现了渔民在风浪中讨生活的艰辛。","当地政府投入专项资金，对百年老街两侧的骑楼进行了修缮。","由于数字流媒体的兴起，近十年来实体唱片的年销量降低了三倍多，许多唱片店被迫关门。","海豚的大脑十分发达，它们能够通过不同频率的声音相互交流。"],"a":2,"type":"배수 감소","why":"판매량이 줄어든 것을 ‘降低了三倍’로 쓸 수 없다. ‘降低了四分之三’이나 ‘降至原来的四分之一’로 써야 한다.","fix":"由于数字流媒体的兴起，近十年来实体唱片的年销量降到了原来的四分之一以下，许多唱片店被迫关门。","words":[["骑楼","qílóu","아케이드식 건물"],["修缮","xiūshàn","보수하다"],["流媒体","liúméitǐ","스트리밍"],["频率","pínlǜ","주파수"],["闽南","Mǐn nán","푸젠 남부"],["长镜头","chángjìngtóu","롱테이크"],["艰辛","jiānxīn","고생스럽다"]],"tr":["민난 어촌을 배경으로 한 이 영화는 롱테이크를 많이 써서 풍랑 속에서 생계를 꾸리는 어민들의 고단함을 보여 준다.","이 지역 정부는 전용 자금을 들여 백 년 된 옛 거리 양쪽의 아케이드식 건물을 보수했다.","디지털 스트리밍이 떠오르면서 최근 10년 사이 실물 음반의 연간 판매량이 크게 줄어, 많은 음반 가게가 어쩔 수 없이 문을 닫았다.","돌고래는 뇌가 매우 발달해서 서로 다른 주파수의 소리로 의사소통을 할 수 있다."],"ow":[[["闽南","Mǐnnán","민난(푸젠 남부)"],["渔村","yúcūn","어촌"],["长镜头","chángjìngtóu","롱테이크"],["艰辛","jiānxīn","고생스럽다"]],[["专项","zhuānxiàng","특정 항목, 전용"],["骑楼","qílóu","아케이드식 건물"],["修缮","xiūshàn","보수하다"]],[["流媒体","liúméitǐ","스트리밍"],["兴起","xīngqǐ","일어나다"],["唱片","chàngpiàn","음반"],["被迫","bèipò","어쩔 수 없이"]],[["海豚","hǎitún","돌고래"],["发达","fādá","발달하다"],["频率","pínlǜ","주파수"]]]},{"o":["古典诗词中常用“鸿雁”来象征书信，这与古代“鸿雁传书”的传说有关。","这家图书馆不仅藏书丰富，还经常举办讲座、读书会等公益活动。","这项研究追踪了三千多名儿童长达二十年，发现早期阅读习惯对其学业表现影响显著。","本次全国展览汇集了来自各地的国画、油画、版画、雕塑和美术作品共三百余件，展期为一个月。"],"a":3,"type":"범위·분류","why":"‘美术作品’은 국화·유화·판화·조각을 모두 포함하는 큰 범주라 나란히 늘어놓을 수 없다.","fix":"本次全国展览汇集了来自各地的国画、油画、版画、雕塑等美术作品共三百余件，展期为一个月。","words":[["鸿雁","hóngyàn","큰기러기"],["象征","xiàngzhēng","상징하다"],["追踪","zhuīzōng","추적하다"],["汇集","huìjí","모으다"],["版画","bǎnhuà","판화"],["雕塑","diāosù","조각"]],"tr":["고전 시가에서는 '큰기러기'로 편지를 상징하는 일이 많은데, 이는 옛날 '기러기가 편지를 전한다'는 전설과 관련이 있다.","이 도서관은 장서가 풍부할 뿐 아니라 강연과 독서 모임 같은 공익 행사도 자주 연다.","이 연구는 3천여 명의 아이를 20년 동안 추적한 끝에, 어릴 적 독서 습관이 학업 성적에 뚜렷한 영향을 준다는 것을 밝혀냈다.","이번 전국 전시회에는 각지에서 온 국화·유화·판화·조각 등 미술 작품 3백여 점이 모였으며, 전시 기간은 한 달이다."],"ow":[[["鸿雁","hóngyàn","큰기러기"],["象征","xiàngzhēng","상징하다"],["书信","shūxìn","편지"],["传说","chuánshuō","전설"]],[["藏书","cángshū","장서"],["讲座","jiǎngzuò","강좌, 강연"],["公益","gōngyì","공익"]],[["追踪","zhuīzōng","추적하다"],["学业","xuéyè","학업"],["显著","xiǎnzhù","뚜렷하다"]],[["汇集","huìjí","모으다"],["版画","bǎnhuà","판화"],["雕塑","diāosù","조각"],["展期","zhǎnqī","전시 기간"]]]},{"o":["这位民间艺人擅长演奏唢呐、笛子、笙、二胡等多种管乐器，在当地小有名气。","春节期间，许多家庭仍保留着贴春联、守岁、拜年等传统习俗。","这片沙漠年降水量不足一百毫米，却生长着梭梭、胡杨等耐旱植物。","这家公司凭借过硬的技术，在短短几年内就打开了东南亚市场。"],"a":0,"type":"범위·분류","why":"‘二胡’는 줄을 켜는 현악기라서 ‘管乐器(관악기)’에 넣을 수 없다.","fix":"这位民间艺人擅长演奏唢呐、笛子、笙、二胡等多种民族乐器，在当地小有名气。","words":[["唢呐","suǒnà","태평소"],["笙","shēng","생황"],["管乐器","guǎnyuèqì","관악기"],["守岁","shǒusuì","섣달그믐 밤을 새우다"],["胡杨","húyáng","호양나무"],["过硬","guòyìng","탄탄하다"]],"tr":["이 민간 예인은 태평소·피리·생황·얼후 등 여러 악기를 잘 다뤄 이 지역에서 꽤 이름이 났다.","설 연휴에는 많은 가정이 지금도 춘련을 붙이고 섣달그믐 밤을 새우고 세배를 다니는 전통 풍습을 지킨다.","이 사막은 연 강수량이 100밀리미터도 안 되지만, 사사나무와 호양나무 같은 가뭄에 강한 식물이 자란다.","이 회사는 탄탄한 기술을 바탕으로 불과 몇 년 만에 동남아 시장을 열었다."],"ow":[[["艺人","yìrén","예인"],["擅长","shàncháng","뛰어나다"],["唢呐","suǒnà","태평소"],["笙","shēng","생황"],["管乐器","guǎnyuèqì","관악기"]],[["春联","chūnlián","춘련(설 대련)"],["守岁","shǒusuì","섣달그믐 밤을 새우다"],["习俗","xísú","풍습"]],[["降水量","jiàngshuǐliàng","강수량"],["梭梭","suōsuō","사사나무(사막 관목)"],["胡杨","húyáng","호양나무"],["耐旱","nàihàn","가뭄에 강하다"]],[["凭借","píngjiè","~에 기대어"],["过硬","guòyìng","탄탄하다"]]]},{"o":["张择端的《清明上河图》中描绘了数以百计的人物，个个神态各异、呼之欲出。","我敢肯定，这幅署名为唐寅的山水画大概是后人仿制的，因为其纸张的年代明显晚于明代。","一些研究者认为，适量饮用咖啡可能有助于降低患某些疾病的风险。","这座古镇因其完好保存的水乡风貌，成为许多影视剧的取景地。"],"a":1,"type":"자기모순","why":"‘肯定(확신한다)’와 ‘大概(아마)’가 서로 부딪친다.","fix":"我敢肯定，这幅署名为唐寅的山水画是后人仿制的，因为其纸张的年代明显晚于明代。","words":[["呼之欲出","hū zhī yù chū","부르면 튀어나올 듯 생생하다"],["署名","shǔmíng","서명하다"],["唐寅","Táng Yín","당인(명대 화가)"],["仿制","fǎngzhì","모조하다"],["取景地","qǔjǐngdì","촬영지"]],"tr":["장택단의 『청명상하도』에는 수백 명의 인물이 그려져 있는데, 하나하나 모습이 달라 금방이라도 튀어나올 듯 생생하다.","나는 당인의 서명이 있는 이 산수화가 후대 사람이 흉내 내 만든 것이라고 확신한다. 종이의 연대가 명나라보다 분명히 늦기 때문이다.","일부 연구자들은 커피를 적당히 마시면 어떤 질병에 걸릴 위험을 낮추는 데 도움이 될 수 있다고 본다.","이 옛 마을은 물의 고장다운 풍경을 온전히 간직하고 있어 많은 영화와 드라마의 촬영지가 되었다."],"ow":[[["张择端","Zhāng Zéduān","장택단(북송 화가)"],["数以百计","shù yǐ bǎi jì","수백에 이르다"],["神态各异","shéntài gè yì","모습이 저마다 다르다"],["呼之欲出","hū zhī yù chū","부르면 튀어나올 듯 생생하다"]],[["署名","shǔmíng","서명하다"],["唐寅","Táng Yín","당인(명대 화가)"],["仿制","fǎngzhì","모조하다"]],[["适量","shìliàng","적당량"],["饮用","yǐnyòng","마시다"]],[["古镇","gǔzhèn","옛 마을"],["水乡","shuǐxiāng","물의 고장"],["风貌","fēngmào","모습"],["取景地","qǔjǐngdì","촬영지"]]]},{"o":["昆曲被誉为“百戏之祖”，对京剧、越剧等许多剧种的形成都产生过重要影响。","每到春季，这里的数十万亩油菜花竞相开放，吸引了大批摄影爱好者。","这位导演执导的电影无一例外地都入围了国际电影节，只有两部遗憾落选。","保持乐观积极的心态，有助于人们更从容地应对生活中的困境。"],"a":2,"type":"자기모순","why":"无一例外(예외 없이 모두 입선)라고 해 놓고 只有两部遗憾落选(두 편은 떨어짐)이라고 해 앞뒤가 모순된다.","fix":"这位导演执导的电影大多入围了国际电影节，只有两部遗憾落选。","words":[["剧种","jùzhǒng","극의 종류"],["竞相","jìngxiāng","앞다투어"],["执导","zhídǎo","감독하다"],["入围","rùwéi","후보에 오르다"],["从容","cóngróng","침착하다"],["困境","kùnjìng","곤경"],["无一例外","wú yī lì wài","하나도 예외 없이"],["落选","luòxuǎn","선발에서 떨어지다"]],"tr":["곤곡은 '백희의 조상'으로 불리며, 경극·월극 등 많은 극 종류가 생겨나는 데 중요한 영향을 주었다.","봄이 오면 이곳의 수십만 무 유채꽃이 앞다투어 피어 수많은 사진 애호가를 끌어들인다.","이 감독이 연출한 영화는 모두 국제 영화제 후보에 올랐는데, 두 편만 아쉽게 떨어졌다.","낙관적이고 적극적인 마음가짐은 사람들이 삶의 곤경에 더 침착하게 대처하도록 돕는다."],"ow":[[["昆曲","kūnqǔ","곤곡"],["被誉为","bèi yùwéi","~로 칭송되다"],["剧种","jùzhǒng","극의 종류"]],[["亩","mǔ","무(면적 단위)"],["油菜花","yóucàihuā","유채꽃"],["竞相","jìngxiāng","앞다투어"]],[["执导","zhídǎo","감독하다"],["无一例外","wú yī lìwài","하나의 예외도 없다"],["入围","rùwéi","후보에 오르다"],["落选","luòxuǎn","떨어지다"]],[["乐观","lèguān","낙관적이다"],["从容","cóngróng","침착하다"],["困境","kùnjìng","곤경"]]]},{"o":["敦煌藏经洞发现于1900年，洞内出土的文书、绢画等文物多达五万余件。","这家剧团常年深入农村巡回演出，一年中有两百多天都在路上。","这种鸟类的雌鸟与雄鸟羽色差异很大，以至于人们曾误把它们当成两个物种。","本届戏剧节共上演剧目四十二台，其中话剧二十台、戏曲十五台、舞剧和音乐剧共十台。"],"a":3,"type":"자기모순","why":"20+15+10=45인데 전체가 42라고 해 앞뒤 숫자가 맞지 않는다.","fix":"本届戏剧节共上演剧目四十五台，其中话剧二十台、戏曲十五台、舞剧和音乐剧共十台。","words":[["藏经洞","cángjīngdòng","장경동"],["绢画","juànhuà","비단 그림"],["巡回","xúnhuí","순회하다"],["雌","cí","암컷"],["以至于","yǐzhìyú","~할 정도로"],["话剧","huàjù","연극"]],"tr":["둔황 장경동은 1900년에 발견되었으며, 동굴 안에서 나온 문서와 비단 그림 등 유물은 5만여 점에 이른다.","이 극단은 일 년 내내 농촌 깊숙이 들어가 순회공연을 하며, 한 해에 이백 일 넘게 길 위에 있다.","이 새는 암수의 깃털 색이 매우 달라서, 사람들이 한때 서로 다른 두 종으로 착각할 정도였다.","이번 연극제에서는 모두 42편이 공연되었는데, 그중 연극이 20편, 전통극이 15편, 무용극과 뮤지컬이 모두 10편이었다."],"ow":[[["敦煌","Dūnhuáng","둔황"],["藏经洞","Cángjīng Dòng","장경동"],["绢画","juànhuà","비단 그림"],["文物","wénwù","문화재, 유물"]],[["剧团","jùtuán","극단"],["常年","chángnián","일 년 내내"],["巡回","xúnhuí","순회하다"]],[["雌","cí","암컷"],["雄","xióng","수컷"],["羽色","yǔsè","깃털 색"],["以至于","yǐzhìyú","~할 정도로"],["物种","wùzhǒng","종"]],[["戏剧节","xìjùjié","연극제"],["剧目","jùmù","공연 레퍼토리"],["话剧","huàjù","연극"],["戏曲","xìqǔ","전통극"],["舞剧","wǔjù","무용극"]]]}],[{"o":["这批明代壁画大面积脱落的主要原因，是长期以来渗水和不当的修复方法所造成的。","宋代以后，中国商船普遍利用季风规律出海，冬季乘东北风南下，夏季借西南风返航。","这位老教授年过八旬仍笔耕不辍，近五年来又出版了两部学术著作。","城市绿地不仅能美化环境，还能有效缓解城市热岛效应、降低噪声污染。"],"a":0,"type":"구식 혼합","why":"“原因是…”와 “是…造成的” 두 구조가 섞였다. 하나만 써야 한다.","fix":"这批明代壁画大面积脱落的主要原因，是长期以来的渗水和不当的修复方法。","words":[["脱落","tuōluò","떨어져 나가다"],["渗水","shènshuǐ","물이 스며들다"],["笔耕不辍","bǐ gēng bú chuò","쉬지 않고 글을 쓰다"],["噪声","zàoshēng","소음"],["季风","jìfēng","계절풍"],["返航","fǎnháng","귀항하다"]],"tr":["이 명대 벽화가 넓게 떨어져 나간 주된 원인은 오랫동안 스며든 물과 잘못된 복원 방법 때문이다.","송나라 이후 중국 상선은 계절풍의 규칙을 이용해 바다로 나갔는데, 겨울엔 북동풍을 타고 남쪽으로 내려가고 여름엔 남서풍을 빌려 돌아왔다.","이 노교수는 여든이 넘어서도 쉬지 않고 글을 써서, 최근 5년 동안 학술 저서 두 권을 더 펴냈다.","도시 녹지는 환경을 아름답게 할 뿐 아니라 열섬 현상을 덜고 소음 공해를 줄이는 데도 효과적이다."],"ow":[[["壁画","bìhuà","벽화"],["脱落","tuōluò","떨어져 나가다"],["渗水","shènshuǐ","물이 스며들다"],["修复","xiūfù","복원하다"]],[["商船","shāngchuán","상선"],["季风","jìfēng","계절풍"],["规律","guīlǜ","규칙"],["返航","fǎnháng","귀항하다"]],[["八旬","bāxún","여든 살"],["笔耕不辍","bǐ gēng bú chuò","쉬지 않고 글을 쓰다"],["著作","zhùzuò","저서"]],[["绿地","lǜdì","녹지"],["缓解","huǎnjiě","완화하다"],["热岛效应","rèdǎo xiàoyìng","열섬 현상"],["噪声","zàoshēng","소음"]]]},{"o":["黄宾虹晚年的山水画浑厚华滋，笔墨愈加苍劲，被人们称为“黑宾虹”。","地中海沿岸夏季炎热干燥、冬季温和多雨，适宜种植橄榄和葡萄。","这份调查报告用翔实的数据说明，青少年近视率上升与户外活动减少密切相关。","早期的民间戏班没有固定的演出场所，他们的收入主要靠在庙会和集市上流动演出为主。"],"a":3,"type":"구식 혼합","why":"“靠…”와 “以…为主” 두 구조가 섞였다. ‘为主’를 빼거나 ‘以…为主’로 써야 한다.","fix":"早期的民间戏班没有固定的演出场所，他们的收入主要靠在庙会和集市上流动演出。","words":[["浑厚华滋","hún hòu huá zī","묵직하고 윤택하다"],["苍劲","cāngjìng","노련하고 힘차다"],["橄榄","gǎnlǎn","올리브"],["翔实","xiángshí","상세하고 확실하다"],["戏班","xìbān","극단"],["庙会","miàohuì","묘회(사당 장터 축제)"]],"tr":["황빈훙의 만년 산수화는 묵직하고 윤택하며 필묵이 더욱 노련하고 힘차서, 사람들은 그를 '검은 빈훙'이라 불렀다.","지중해 연안은 여름에 덥고 건조하며 겨울에 온화하고 비가 많아 올리브와 포도를 기르기에 알맞다.","이 조사 보고서는 상세하고 확실한 자료로, 청소년 근시율이 오른 것이 바깥 활동이 줄어든 것과 밀접한 관련이 있음을 보여 준다.","초기 민간 극단은 정해진 공연장이 없어서, 수입은 주로 묘회와 장터를 돌며 하는 공연에 기댔다."],"ow":[[["黄宾虹","Huáng Bīnhóng","황빈훙(근대 화가)"],["浑厚华滋","hún hòu huá zī","묵직하고 윤택하다"],["笔墨","bǐmò","필묵"],["苍劲","cāngjìng","노련하고 힘차다"]],[["地中海","Dìzhōnghǎi","지중해"],["沿岸","yán'àn","연안"],["适宜","shìyí","알맞다"],["橄榄","gǎnlǎn","올리브"]],[["翔实","xiángshí","상세하고 확실하다"],["近视","jìnshì","근시"],["密切","mìqiè","밀접하다"]],[["戏班","xìbān","극단"],["场所","chǎngsuǒ","장소"],["庙会","miàohuì","묘회(사당 장터 축제)"],["集市","jíshì","장터"],["流动","liúdòng","이동하다"]]]},{"o":["苏轼在《赤壁赋》中借江水与明月，表达了对宇宙和人生的深刻思考。","这项文化惠民工程以让偏远山区的群众也能看上高质量的文艺演出为目的而开展起来的。","盐碱地经过多年改良，如今已能种植水稻，亩产甚至超过了五百公斤。","由于常年在海外演出，这位歌唱家对异国观众的欣赏习惯了如指掌。"],"a":1,"type":"구식 혼합","why":"“以…为目的而开展”과 “是…开展起来的”가 섞였다. 문장 끝 ‘的’에 맞는 ‘是’가 빠졌다.","fix":"这项文化惠民工程是以让偏远山区的群众也能看上高质量的文艺演出为目的而开展起来的。","words":[["赤壁赋","Chì bì fù","적벽부"],["惠民","huìmín","백성을 이롭게 하다"],["盐碱地","yánjiǎndì","염알칼리 토지"],["改良","gǎiliáng","개량하다"],["了如指掌","liǎo rú zhǐ zhǎng","손바닥 보듯 훤하다"]],"tr":["소식은 『적벽부』에서 강물과 밝은 달을 빌려 우주와 인생에 대한 깊은 사색을 드러냈다.","이 문화 혜민 사업은 외딴 산골 주민들도 수준 높은 문예 공연을 볼 수 있게 하려는 목적으로 시작되었다.","염알칼리 땅은 여러 해 개량을 거쳐 이제 벼를 심을 수 있게 되었고, 무당 수확량이 500킬로그램을 넘기도 했다.","이 가수는 해외 공연을 오래 해 왔기 때문에 외국 관객의 감상 습관을 손바닥 보듯 훤히 안다."],"ow":[[["苏轼","Sū Shì","소식"],["赤壁赋","Chìbì Fù","적벽부"],["宇宙","yǔzhòu","우주"]],[["惠民","huìmín","백성을 이롭게 하다"],["偏远","piānyuǎn","외지고 멀다"],["文艺","wényì","문예"]],[["盐碱地","yánjiǎndì","염알칼리 토지"],["改良","gǎiliáng","개량하다"],["亩产","mǔchǎn","무당 생산량"]],[["常年","chángnián","일 년 내내"],["异国","yìguó","외국"],["了如指掌","liǎo rú zhǐ zhǎng","손바닥 보듯 훤하다"]]]},{"o":["京剧脸谱中，红色多表示忠勇，黑色多表示刚直，白色则多表示奸诈。","研究发现，章鱼不仅能够改变体色，还能根据环境改变皮肤表面的纹理。","一部历史剧赢得观众的口碑，关键在于创作者对历史细节的尊重起着决定性的作用。","他把整理好的家族族谱捐献给了地方档案馆，供研究者查阅。"],"a":2,"type":"구식 혼합","why":"“关键在于…”와 “…起着决定性的作用”이 섞였다. 하나만 써야 한다.","fix":"一部历史剧赢得观众的口碑，关键在于创作者对历史细节的尊重。","words":[["刚直","gāngzhí","강직하다"],["奸诈","jiānzhà","간사하다"],["章鱼","zhāngyú","문어"],["纹理","wénlǐ","무늬, 결"],["口碑","kǒubēi","입소문, 평판"],["族谱","zúpǔ","족보"]],"tr":["경극 얼굴 분장에서 빨강은 대개 충성과 용맹을, 검정은 강직함을, 하양은 간사함을 나타낸다.","연구에 따르면 문어는 몸 색을 바꿀 뿐 아니라 환경에 따라 피부 표면의 결까지 바꿀 수 있다.","사극이 관객의 좋은 평판을 얻느냐는 결국 창작자가 역사의 세부를 얼마나 존중하느냐에 달려 있다.","그는 정리한 집안 족보를 지방 기록 보관소에 기증해 연구자들이 열람할 수 있게 했다."],"ow":[[["脸谱","liǎnpǔ","(경극) 얼굴 분장"],["忠勇","zhōngyǒng","충성스럽고 용감하다"],["刚直","gāngzhí","강직하다"],["奸诈","jiānzhà","간사하다"]],[["章鱼","zhāngyú","문어"],["体色","tǐsè","몸 색"],["纹理","wénlǐ","무늬, 결"]],[["口碑","kǒubēi","입소문, 평판"],["关键在于","guānjiàn zàiyú","관건은 ~에 있다"],["细节","xìjié","세부"]],[["族谱","zúpǔ","족보"],["捐献","juānxiàn","기증하다"],["档案馆","dàng'ànguǎn","기록 보관소"],["查阅","cháyuè","열람하다"]]]},{"o":["自从这部讲述非遗传承人故事的纪录片在网络平台上线以来，使不少年轻人开始对传统手工艺产生了浓厚兴趣。","引航员需要登上进港的大型船舶，凭借对航道水文的熟悉，引导船只安全靠泊码头。","他虽然身居要职，却始终保持着清廉节俭的作风，深受百姓爱戴。","这座古桥由当地乡绅集资修建，桥身全部采用青石砌成，历经数百年风雨依然坚固。"],"a":0,"type":"주어 결여","why":"“自从…以来，使…” 때문에 주어가 없다. ‘使’를 빼야 ‘不少年轻人’이 주어가 된다.","fix":"自从这部讲述非遗传承人故事的纪录片在网络平台上线以来，不少年轻人开始对传统手工艺产生了浓厚兴趣。","words":[["非遗","fēiyí","무형 문화유산"],["传承人","chuánchéngrén","전승자"],["清廉","qīnglián","청렴하다"],["乡绅","xiāngshēn","향신(지방 유지)"],["砌","qì","(돌을) 쌓다"],["引航员","yǐnhángyuán","도선사"],["船舶","chuánbó","선박"],["靠泊","kàobó","정박하다"]],"tr":["무형 문화유산 전승자의 이야기를 담은 이 다큐멘터리가 인터넷에 공개된 뒤로, 많은 젊은이들이 전통 수공예에 큰 관심을 갖기 시작했다.","도선사는 항구로 들어오는 대형 선박에 올라 항로와 물길 사정에 대한 지식을 바탕으로 배가 부두에 안전하게 대도록 이끈다.","그는 높은 자리에 있으면서도 늘 청렴하고 검소한 태도를 지켜 백성들에게 깊은 존경과 사랑을 받았다.","이 옛 다리는 지역 유지들이 돈을 모아 세운 것으로, 다리 몸체를 모두 푸른 돌로 쌓아 수백 년의 비바람을 겪고도 여전히 튼튼하다."],"ow":[[["非遗","fēiyí","무형 문화유산"],["传承人","chuánchéngrén","전승자"],["纪录片","jìlùpiàn","다큐멘터리"],["浓厚","nónghòu","짙다"]],[["引航员","yǐnhángyuán","도선사"],["船舶","chuánbó","선박"],["航道","hángdào","항로"],["水文","shuǐwén","수문(물길 사정)"],["靠泊","kàobó","정박하다"]],[["身居要职","shēn jū yào zhí","요직에 있다"],["清廉","qīnglián","청렴하다"],["节俭","jiéjiǎn","검소하다"],["爱戴","àidài","존경하고 따르다"]],[["乡绅","xiāngshēn","향신(지방 유지)"],["集资","jízī","자금을 모으다"],["砌","qì","(돌을) 쌓다"],["历经","lìjīng","두루 겪다"]]]},{"o":["北宋画家范宽的《溪山行旅图》气势雄伟，被不少人誉为“宋画第一”。","这家养老院为老人们开设了书法、合唱和太极拳等兴趣课程，丰富了他们的晚年生活。","科学家估计，地球上的物种中至今仍有相当大一部分尚未被人类发现和命名。","作者在序言中坦言，他并不否认书中对部分历史人物的评价没有失之偏颇的地方。"],"a":3,"type":"다중 부정","why":"‘不否认(부정하지 않는다)’ 뒤에 ‘没有’를 붙여 ‘치우친 곳이 없다’는 정반대 뜻이 되었다.","fix":"作者在序言中坦言，他并不否认书中对部分历史人物的评价有失之偏颇的地方。","words":[["范宽","Fàn Kuān","범관(북송 화가)"],["溪山行旅图","Xī shān xíng lǚ tú","계산행려도"],["命名","mìngmíng","이름 붙이다"],["序言","xùyán","서문"],["否认","fǒurèn","부인하다"],["失之偏颇","shī zhī piān pō","한쪽으로 치우치다"]],"tr":["북송 화가 범관의 『계산행려도』는 기세가 웅장해서 많은 이들에게 '송화 제일'로 칭송된다.","이 양로원은 노인들을 위해 서예·합창·태극권 같은 취미 강좌를 열어 그들의 노년 생활을 풍요롭게 했다.","과학자들은 지구상의 생물 종 가운데 상당 부분이 아직 사람에게 발견되지도 이름 붙여지지도 않았다고 추정한다.","지은이는 서문에서, 책 속 일부 역사 인물에 대한 평가가 한쪽으로 치우친 곳이 있음을 부정하지 않는다고 솔직히 밝혔다."],"ow":[[["范宽","Fàn Kuān","범관(북송 화가)"],["溪山行旅图","Xīshān Xínglǚ Tú","계산행려도"],["雄伟","xióngwěi","웅장하다"]],[["养老院","yǎnglǎoyuàn","양로원"],["太极拳","tàijíquán","태극권"],["晚年","wǎnnián","만년, 노년"]],[["估计","gūjì","추정하다"],["物种","wùzhǒng","종"],["尚未","shàngwèi","아직 ~않다"],["命名","mìngmíng","이름 붙이다"]],[["序言","xùyán","서문"],["坦言","tǎnyán","솔직히 말하다"],["否认","fǒurèn","부인하다"],["失之偏颇","shī zhī piānpō","한쪽으로 치우치다"]]]},{"o":["这首民间渔歌曲调悠长舒缓，唱出了渔家女子盼望亲人平安归来的深切思念。","一个地方的传统戏曲能不能得到很好的传承，是当地文化事业繁荣发展的重要标志。","植物的叶片之所以在秋天变黄，是因为叶绿素逐渐分解，叶黄素的颜色显现了出来。","这次地铁线路调整后，从新城区到老城中心的通勤时间缩短了二十分钟。"],"a":1,"type":"양면–한면","why":"能不能(될 수도 안 될 수도)은 양쪽을 말하는데, 繁荣发展的重要标志(번영의 표지)는 잘 될 때만 맞는 말이라 앞뒤가 맞지 않는다.","fix":"一个地方的传统戏曲得到很好的传承，是当地文化事业繁荣发展的重要标志。","words":[["传承","chuánchéng","전승하다"],["叶绿素","yèlǜsù","엽록소"],["通勤","tōngqín","통근"],["悠长","yōucháng","길게 이어지다"],["舒缓","shūhuǎn","느긋하다"],["标志","biāozhì","표지, 상징"]],"tr":["이 민간 어부의 노래는 가락이 길고 느긋하며, 가족이 무사히 돌아오기를 바라는 어촌 여인의 깊은 그리움을 담아 냈다.","한 지역의 전통 희곡이 잘 전승되는 것은 그 지역 문화 사업이 번영하고 있다는 중요한 지표다.","가을에 식물 잎이 노래지는 것은 엽록소가 차츰 분해되면서 엽황소의 색이 드러나기 때문이다.","이번 지하철 노선 조정 뒤 신시가지에서 구시가지 중심까지의 통근 시간이 20분 줄었다."],"ow":[[["渔歌","yúgē","어부의 노래"],["悠长","yōucháng","길게 이어지다"],["舒缓","shūhuǎn","느긋하다"],["盼望","pànwàng","간절히 바라다"]],[["戏曲","xìqǔ","희곡, 전통극"],["传承","chuánchéng","전승하다"],["繁荣","fánróng","번영하다"],["标志","biāozhì","지표, 상징"]],[["叶绿素","yèlǜsù","엽록소"],["分解","fēnjiě","분해하다"],["叶黄素","yèhuángsù","엽황소"],["显现","xiǎnxiàn","드러나다"]],[["线路","xiànlù","노선"],["调整","tiáozhěng","조정하다"],["通勤","tōngqín","통근"]]]},{"o":["茅盾文学奖每四年评选一次，是中国长篇小说领域的最高奖项之一。","长期以来，人们一直认为恐龙是冷血动物，但近年来的研究对此提出了挑战。","经过近两年的精心修缮，这座百年剧院不仅保留了原有的建筑风貌，还大大改善了观众的观演。","这套海洋气象浮标系统可以实时采集风速、浪高等数据，为过往船只提供预警。"],"a":2,"type":"목적어 결여","why":"“改善了观众的观演” 뒤에 중심 명사가 없다. ‘观演体验’이나 ‘观演条件’이 있어야 한다.","fix":"经过近两年的精心修缮，这座百年剧院不仅保留了原有的建筑风貌，还大大改善了观众的观演体验。","words":[["茅盾","Máo Dùn","마오둔(작가)"],["评选","píngxuǎn","심사하여 뽑다"],["恐龙","kǒnglóng","공룡"],["修缮","xiūshàn","보수하다"],["风貌","fēngmào","모습"],["浮标","fúbiāo","부표"],["预警","yùjǐng","사전 경보"]],"tr":["마오둔 문학상은 4년마다 한 번 수상작을 뽑으며, 중국 장편소설 분야의 최고 상 가운데 하나다.","오랫동안 사람들은 공룡을 냉혈 동물로 여겨 왔지만, 최근 연구가 이 생각에 이의를 제기했다.","2년 가까이 정성껏 보수한 끝에, 이 백 년 된 극장은 원래의 건축 모습을 지켰을 뿐 아니라 관객의 관람 환경도 크게 개선했다.","이 해양 기상 부표 시스템은 풍속과 파고 같은 자료를 실시간으로 모아 지나가는 배들에게 사전 경보를 준다."],"ow":[[["茅盾","Máo Dùn","마오둔(작가)"],["评选","píngxuǎn","심사하여 뽑다"],["奖项","jiǎngxiàng","상"]],[["恐龙","kǒnglóng","공룡"],["冷血动物","lěngxuè dòngwù","냉혈 동물"],["挑战","tiǎozhàn","도전, 이의"]],[["修缮","xiūshàn","보수하다"],["剧院","jùyuàn","극장"],["风貌","fēngmào","모습"],["观演","guānyǎn","공연 관람"]],[["浮标","fúbiāo","부표"],["实时","shíshí","실시간"],["采集","cǎijí","수집하다"],["预警","yùjǐng","사전 경보"]]]},{"o":["尽管这首民歌的旋律简单质朴，因此一经传唱就在大江南北广为流行。","中医认为，人体的健康有赖于阴阳的平衡，一旦失衡便容易生病。","他坚信，只有不断吸收新的知识，才能在激烈的竞争中立于不败之地。","这条古道曾是连接川藏两地的重要商路，马帮驮着茶叶和盐巴在崇山峻岭间穿行。"],"a":0,"type":"짝 오류","why":"‘尽管’은 ‘却·但’과 짝을 이룬다. 뒤에 ‘因此’를 써서 역접이 인과로 바뀌었다.","fix":"尽管这首民歌的旋律简单质朴，却一经传唱就在大江南北广为流行。","words":[["旋律","xuánlǜ","선율"],["大江南北","dà jiāng nán běi","전국 각지"],["有赖于","yǒulàiyú","~에 달려 있다"],["立于不败之地","lì yú bú bài zhī dì","지지 않는 자리에 서다"],["马帮","mǎbāng","말 짐꾼 무리"],["驮","tuó","(등에) 싣다"],["崇山峻岭","chóng shān jùn lǐng","높고 험한 산들"]],"tr":["이 민요는 선율이 단순하고 소박하지만, 불리기 시작하자마자 전국 각지로 널리 퍼졌다.","한의학에서는 사람의 건강이 음양의 균형에 달려 있어서, 균형이 깨지면 병이 나기 쉽다고 본다.","그는 새로운 지식을 끊임없이 받아들여야만 치열한 경쟁에서 지지 않을 수 있다고 굳게 믿는다.","이 옛길은 쓰촨과 티베트를 잇는 중요한 교역로였으며, 말 짐꾼 무리가 차와 소금을 싣고 높고 험한 산들 사이를 오갔다."],"ow":[[["旋律","xuánlǜ","선율"],["质朴","zhìpǔ","소박하다"],["传唱","chuánchàng","불리며 전해지다"],["大江南北","dà jiāng nán běi","전국 각지"]],[["中医","zhōngyī","한의학"],["有赖于","yǒulàiyú","~에 달려 있다"],["阴阳","yīnyáng","음양"],["失衡","shīhéng","균형을 잃다"]],[["坚信","jiānxìn","굳게 믿다"],["吸收","xīshōu","흡수하다"],["立于不败之地","lì yú bú bài zhī dì","지지 않는 자리에 서다"]],[["川藏","Chuān-Zàng","쓰촨과 티베트"],["马帮","mǎbāng","말 짐꾼 무리"],["驮","tuó","(등에) 싣다"],["盐巴","yánbā","소금"],["崇山峻岭","chóng shān jùn lǐng","높고 험한 산들"]]]},{"o":["王羲之被后人尊为“书圣”，他的儿子王献之也是一位杰出的书法家，父子二人并称“二王”。","这一带的喀斯特地貌发育典型，地下溶洞纵横交错，钟乳石千姿百态。","为了保护视力，眼科医生建议连续用眼四十分钟左右就应休息一会儿。","这位作家的稿酬收入在当时相当可观，一部长篇小说的版税就有三千余元上下，足以在北京买下一座小四合院。"],"a":3,"type":"어림수 중복","why":"‘余’와 ‘上下’가 모두 어림수를 나타내 겹친다.","fix":"这位作家的稿酬收入在当时相当可观，一部长篇小说的版税就有三千余元，足以在北京买下一座小四合院。","words":[["书圣","shūshèng","서성(서예의 성인)"],["喀斯特","kāsītè","카르스트"],["溶洞","róngdòng","석회 동굴"],["钟乳石","zhōngrǔshí","종유석"],["稿酬","gǎochóu","원고료"],["版税","bǎnshuì","인세"],["四合院","sìhéyuàn","사합원"]],"tr":["왕희지는 후대 사람들에게 '서성'으로 받들어졌고, 아들 왕헌지도 뛰어난 서예가여서 부자를 함께 '이왕'이라 부른다.","이 일대는 카르스트 지형이 전형적으로 발달해, 땅속 석회 동굴이 사방으로 얽혀 있고 종유석의 모양이 갖가지다.","시력을 지키려면 40분 정도 계속 눈을 쓴 뒤에는 잠깐 쉬어야 한다고 안과 의사는 권한다.","이 작가의 원고료 수입은 당시로서는 꽤 많아서, 장편소설 한 편의 인세만 3천여 위안에 이르러 베이징에 작은 사합원 한 채를 살 수 있을 정도였다."],"ow":[[["王羲之","Wáng Xīzhī","왕희지"],["书圣","shūshèng","서성(서예의 성인)"],["王献之","Wáng Xiànzhī","왕헌지"],["杰出","jiéchū","걸출하다"]],[["喀斯特","kāsītè","카르스트"],["地貌","dìmào","지형"],["溶洞","róngdòng","석회 동굴"],["纵横交错","zònghéng jiāocuò","가로세로로 얽히다"],["钟乳石","zhōngrǔshí","종유석"],["千姿百态","qiān zī bǎi tài","갖가지 모습"]],[["视力","shìlì","시력"],["眼科","yǎnkē","안과"]],[["稿酬","gǎochóu","원고료"],["可观","kěguān","상당하다"],["版税","bǎnshuì","인세"],["四合院","sìhéyuàn","사합원"]]]}]];
